var BAB=[
{n:'I',t:'Al-Quran adalah wahyu Allah',sub:['Pengertian Al-Quran','Nama-nama Al-Quran','Perilaku orang yang memahami Al-Quran'],um:'Berpikir ilmiah dan memilah data benar atau keliru, dikaitkan dengan makna Al-Furqan',so:'Budaya literasi, tabayun di era media sosial, hidup di masyarakat yang beragam',sample:'Mengapa belajar dan membaca penting menurut Al-Quran?',qs:[
{q:"Secara bahasa, ada beberapa pendapat ulama tentang arti kata Al-Quran. Sebutkan satu pendapat yang kamu ingat dan jelaskan maksudnya.",a:"Ada lima pendapat utama. Al-Lihyani: Al-Quran berarti bacaan. Al-Asy'ari: menggabungkan. Al-Farra': petunjuk atau indikator. Az-Zajjaj: kumpulan. Asy-Syafi'i: nama asli tanpa asal kata. Abu Syuhbah menilai pendapat Al-Lihyani paling tepat dan paling masyhur, dan perbedaan pendapat ini justru saling melengkapi.",ref:"QS. Al-Qiyamah: 17-18",ay:["75:17-18"],hd:[],um:"Seperti ilmuwan yang menggabungkan banyak data dari beberapa metode untuk satu kesimpulan, pendapat yang berbeda bisa saling melengkapi.",so:"Tradisi baca-tulis dan hafalan membentuk budaya literasi di masyarakat Islam."},
{q:"Sebutkan satu nama lain Al-Quran, lalu hubungkan maknanya dengan kehidupan sehari-hari.",a:"Al-Quran punya banyak nama; Imam Suyuthi menyebut 55 nama. Yang populer: Al-Kitab (yang ditulis), Al-Furqan (pembeda yang hak dan yang batil), Az-Zikr (peringatan, yang dipelihara Allah), dan At-Tanzil (yang diturunkan).",ref:"QS. Al-Baqarah: 2, QS. Al-Furqan: 1, QS. Al-Hijr: 9, QS. Asy-Syu'ara: 192",ay:["2:2", "25:1", "15:9", "26:192"],hd:[],um:"Fungsi Al-Furqan sejalan dengan berpikir ilmiah, yaitu membedakan klaim yang benar dari yang keliru dengan bukti.",so:"Di era media sosial, sikap tabayun memilah informasi mencegah hoaks yang memecah masyarakat."},
{q:"Bagaimana seorang muslim menunjukkan perilaku memahami Al-Quran, baik saat sendiri maupun di tengah masyarakat yang beragam?",a:"Orang yang memahami Al-Quran berpegang pada akidah, ibadah, dan akhlak, serta menjalankannya baik saat sendiri maupun di tengah masyarakat yang seragam atau beragam. Ia berpikir, bersikap, dan bertindak menurut tuntunan Al-Quran, termasuk menyimak dengan tenang ketika dibacakan.",ref:"QS. Al-Baqarah: 185, QS. Al-A'raf: 204",ay:["2:185", "7:204"],hd:[],um:"Menyimak dengan fokus melatih konsentrasi, dan latihan fokus membantu proses belajar.",so:"Di masyarakat heterogen, akhlak mulia, toleransi, dan kerja sama menjadi wujud nyata memahami Al-Quran."}]},
{n:'II',t:'Kebenaran penurunan Al-Quran',sub:['Pengertian turunnya Al-Quran','Kaifiyat turunnya (perbedaan pendapat ulama)','Penulisan: zaman Nabi, Abu Bakar, Utsman'],um:'Standarisasi: banyak catatan disatukan menjadi satu naskah induk agar informasi konsisten',so:'Penyatuan mushaf menjaga persatuan dan mencegah perpecahan karena beda bacaan',sample:'Bagaimana Al-Quran dikumpulkan menjadi satu mushaf?',qs:[
{q:"Sebutkan tiga fase penulisan dan pengumpulan Al-Quran, lalu jelaskan mengapa Khalifah Utsman menyatukan mushaf.",a:"Tiga fase: masa Nabi (hafalan sahabat lebih dominan, tulisan masih terpisah di pelepah kurma, kulit, dan batu), masa Abu Bakar (dikumpulkan dalam satu mushaf oleh Zaid bin Tsabit setelah banyak penghafal gugur di perang Yamamah), dan masa Utsman (disatukan dengan dialek Quraisy lalu disebarkan ke berbagai negeri). Penyatuan dilakukan agar perbedaan bacaan tidak memicu pertengkaran dan perpecahan.",ref:"QS. Al-Hijr: 9",ay:["15:9"],hd:[],um:"Menyatukan banyak catatan menjadi satu naskah induk mirip standarisasi data: semua salinan merujuk satu sumber agar isinya konsisten.",so:"Satu mushaf menjaga persatuan umat dan mencegah perselisihan akibat perbedaan bacaan."},
{q:"Mengapa pada masa Nabi hafalan lebih berperan daripada tulisan, dan apa pelajarannya untuk cara belajar kita?",a:"Pada masa Nabi, siapa pun yang mendengar ayat langsung menghafal atau menuliskannya dengan sarana seadanya, dan jumlah penghafalnya sangat banyak. Hafalan dan tulisan saling menjaga sehingga Al-Quran tidak bergantung pada satu cara saja.",ref:"QS. Al-Qiyamah: 17-18 dan QS. Al-Hijr: 9",ay:["75:17-18", "15:9"],hd:[],um:"Menyimpan informasi di lebih dari satu tempat (ingatan dan catatan) adalah prinsip cadangan data: bila satu hilang, yang lain menjaga.",so:"Komunitas belajar yang saling menyimak dan mengoreksi bacaan menguatkan penjagaan ilmu antargenerasi."}]},
{n:'III',t:'Menghayati keotentikan Al-Quran',sub:['Keotentikan dan penjagaan Al-Quran','Tantangan Al-Quran (tiga tingkat)','Peran penghafal sepanjang zaman'],um:'Klaim diuji dengan bukti yang bisa dicek ulang; sumber terverifikasi lebih dipercaya',so:'Berita viral salah cetak dan hoaks: tabayun, peran penghafal dan percetakan resmi',sample:'Bagaimana keaslian Al-Quran terjaga sampai sekarang?',qs:[
{q:"Apa saja tantangan Al-Quran bagi orang yang meragukannya, dan apa kesimpulan dari tantangan itu?",a:"Al-Quran menantang tiga tingkat: membuat semisal seluruh Al-Quran, membuat sepuluh surah, lalu cukup satu surah. Hingga kini tidak ada yang mampu, sehingga ini dipahami sebagai bukti bahwa Al-Quran wahyu Allah, bukan karangan manusia.",ref:"QS. Al-Isra: 88, QS. At-Tur: 33-34, QS. Hud: 13, QS. Al-Baqarah: 23",ay:["17:88", "52:33-34", "11:13", "2:23"],hd:[],um:"Tantangan ini terbuka untuk dibuktikan siapa saja, mirip sikap ilmiah bahwa klaim sebaiknya dapat diuji dan dicek ulang.",so:"Sejak dahulu pihak yang meragukan menuduhnya karangan atau syair; jawaban Al-Quran berupa tantangan terbuka di tengah masyarakat."},
{q:"Ada berita viral tentang Al-Quran yang salah cetak. Bagaimana sikapmu, dan mengapa kekeliruan seperti itu mudah diketahui?",a:"Kekeliruan cetak mudah diketahui karena banyak penghafal dan semua cetakan merujuk satu mushaf standar dari masa Utsman. Sikap yang benar adalah memeriksa kabarnya dulu sebelum membagikannya.",ref:"QS. Al-Hujurat: 6 dan QS. Al-Hijr: 9",ay:["49:6", "15:9"],hd:[],um:"Verifikasi dilakukan dengan membandingkan beberapa sumber tepercaya, seperti mushaf yang disahkan lembaga resmi, bukan hanya satu unggahan.",so:"Hoaks digital menyebar cepat; kebiasaan tabayun melindungi masyarakat dari kepanikan dan perpecahan."}]},
{n:'IV',t:'Al-Quran mukjizat Nabiku',sub:['Pengertian dan syarat mukjizat','Mukjizat hissi dan ma\'nawi','Aspek bahasa dan isi (i\'jaz)','Mukjizat para nabi','Isyarat ilmiah dalam Al-Quran'],um:'Mukjizat melampaui kebiasaan hukum alam, sehingga berbeda ranah dengan eksperimen sains',so:'Mukjizat sesuai keunggulan zaman umatnya: sihir, kedokteran, sastra',sample:'Apa itu mukjizat dan apa bedanya mukjizat hissi dengan maknawi?',qs:[
{q:"Jelaskan perbedaan mukjizat hissi dan ma'nawi, lalu beri contohnya.",a:"Mukjizat hissi dapat ditangkap panca indera dan dibatasi ruang serta waktu, misalnya tongkat Nabi Musa atau api yang menjadi dingin bagi Nabi Ibrahim. Mukjizat ma'nawi dipahami dengan akal dan hati serta bersifat universal dan abadi, yaitu Al-Quran.",ref:"QS. Al-A'raf: 107, QS. Al-Anbiya: 68-69, QS. Al-Baqarah: 23",ay:["7:107", "21:68-69", "2:23"],hd:[],um:"Mukjizat melampaui kebiasaan hukum alam (sunnatullah), sehingga tidak diuji dengan eksperimen sains yang meneliti keteraturan alam; keduanya berada di ranah yang berbeda.",so:"Mukjizat para nabi sesuai keunggulan zaman umatnya: sihir pada masa Musa, kedokteran pada masa Isa, dan sastra Arab pada masa Nabi Muhammad."},
{q:"Sebutkan aspek kemukjizatan Al-Quran dari segi bahasa dan isi.",a:"Dari bahasa: gaya bahasa (uslub) yang indah, serasi, dan tidak bisa ditiru. Dari isi: kabar gaib masa lalu dan masa depan (misalnya kemenangan Romawi), isyarat ilmu pengetahuan, serta hukum yang universal.",ref:"QS. Ar-Rum: 1-3, QS. Yunus: 92, QS. Fussilat: 53",ay:["30:1-3", "10:92", "41:53"],hd:[],um:"Kaitan ayat dengan temuan sains dilihat dengan hati-hati karena teori ilmiah bisa berkembang. Pola jumlah huruf dan kata yang sering disebut juga diperdebatkan cara menghitungnya, jadi perlu diperiksa ulang sebelum dijadikan dalil.",so:"Kisah bangsa Romawi dan Persia menunjukkan bahwa sejarah dan politik antarbangsa pun disinggung Al-Quran."},
{q:"Sebagian orang mengaitkan ayat dengan temuan sains, misalnya sidik jari dan oksigen di ketinggian. Bagaimana sikap yang tepat terhadap kaitan ini?",a:"Isyarat ilmiah dibaca sebagai bahan renungan. QS. Al-Qiyamah: 3-4 menyebut Allah mampu menyusun kembali ujung jari (banan), dan sebagian penafsir masa kini mengaitkannya dengan keunikan sidik jari. QS. Al-An'am: 125 menggambarkan dada yang sesak seperti orang yang mendaki ke langit, dan sebagian pemikir mengaitkannya dengan menipisnya oksigen di ketinggian. Penafsiran semacam ini beragam di kalangan ulama.",ref:"QS. Al-Qiyamah: 3-4, QS. Al-An'am: 125",ay:["75:3-4","6:125"],hd:[],um:"Catatan: teori ilmiah bisa berkembang, sehingga ayat tidak digantungkan pada satu teori. Kaitan dengan sains dipakai untuk merenung, sedangkan makna ayat tetap merujuk pada tafsir ulama.",so:"Menyebarkan klaim ayat sesuai sains tanpa memeriksa sumbernya bisa menimbulkan salah paham di masyarakat, jadi budaya tabayun tetap diperlukan."}]},
{n:'V',t:'Kebenaran Al-Quran pada semua aspek kehidupan',sub:['Akidah','Ibadah dan muamalah','Akhlak','Hukum','Kisah umat terdahulu','Dasar sains dan teknologi'],um:'Al-Quran mendorong sains dan teknologi: kedokteran, matematika, pertanian',so:'Muamalah dan hukum, akhlak, serta kisah umat lalu sebagai pelajaran sejarah',sample:'Bagaimana akhlak Nabi menjadi teladan bagi kita?',qs:[
{q:"Sebutkan isi pokok ajaran Al-Quran dan jelaskan hubungan antara ibadah kepada Allah dan muamalah dengan sesama.",a:"Isi pokoknya meliputi akidah, ibadah dan muamalah, akhlak, hukum, kisah umat terdahulu, serta dasar sains dan teknologi. Hablun minallah mengatur hubungan dengan Allah, hablun minannas mengatur hubungan antarmanusia, dan pekerjaan halal yang diniatkan ibadah pun bernilai ibadah.",ref:"QS. Al-Ikhlas: 1-4, QS. Adz-Dzariyat: 56, QS. Al-Baqarah: 282",ay:["112:1-4", "51:56", "2:282"],hd:[],um:"Perintah mencatat utang dalam QS. Al-Baqarah: 282 sejalan dengan prinsip pencatatan dan akuntansi yang rapi.",so:"Transaksi yang tertulis dan disaksikan mencegah sengketa dan menjaga kepercayaan dalam ekonomi masyarakat."},
{q:"Bagaimana akhlak Nabi Muhammad menjadi teladan di lingkungan sekolah dan masyarakat kita?",a:"Nabi diutus untuk menyempurnakan akhlak, dan Aisyah r.a. menyebut akhlak beliau adalah Al-Quran. Meneladani beliau berarti menerapkan kejujuran, kasih sayang, dan tanggung jawab dalam kehidupan sehari-hari.",ref:"QS. Al-Qalam: 4, QS. Al-Ahzab: 21, dan hadis riwayat Ahmad no. 8952 dan Muslim no. 746",ay:["68:4", "33:21"],hd:["ahmad8952", "muslim746"],um:"Psikologi belajar sosial menunjukkan orang cenderung meniru perilaku orang yang diteladani, sehingga keteladanan efektif membentuk karakter.",so:"Kisah umat terdahulu menjadi pelajaran sejarah (ibrah) agar masyarakat meniru kebaikan dan menjauhi keburukan."}]},
{n:'VI',t:'Kebenaran Al-Quran berlaku sepanjang zaman',sub:['Komposisi: surah, juz, manzil','Makkiyah dan Madaniyah','Maqra\' atau ruku\'','Basmalah','Mu\'jam (kamus Al-Quran)'],um:'Pembagian juz dan manzil seperti manajemen waktu belajar; mu\'jam seperti indeks pencarian',so:'Makkiyah dan Madaniyah mencerminkan fase dakwah di Makkah dan Madinah',sample:'Apa perbedaan ayat Makkiyah dan Madaniyah?',qs:[
{q:"Jelaskan pembagian Al-Quran (surah, juz, manzil) serta ciri ayat Makkiyah dan Madaniyah.",a:"Al-Quran terdiri dari 114 surah dan 30 juz; manzil membaginya menjadi 7 bagian agar bisa khatam dalam seminggu. Makkiyah turun sebelum hijrah, cenderung pendek dan membahas iman serta akhlak; Madaniyah turun setelah hijrah, cenderung panjang dan memuat hukum serta aturan bermasyarakat.",ref:"QS. Al-Ikhlas dan An-Nas (contoh Makkiyah); QS. Al-Baqarah dan Ali Imran (contoh Madaniyah)",um:"Pembagian juz dan manzil mirip manajemen waktu: target kecil yang teratur membuat tugas besar lebih mudah diselesaikan.",so:"Di Makkah dakwah menguatkan fondasi iman, sedangkan di Madinah umat membangun masyarakat dengan aturan sosial dan hukum."},
{q:"Bagaimana cara mencari ayat tertentu dan memanfaatkan teknologi untuk belajar Al-Quran dengan benar?",a:"Ayat tertentu bisa dicari lewat mu'jam (kamus Al-Quran), misalnya karya Muhammad Fuad Abdul Baqi, dan kini juga lewat aplikasi mushaf digital. Pilihlah sumber yang jelas dan terverifikasi, lalu cocokkan dengan terjemahan dan penjelasan dari guru.",ref:"QS. Al-Alaq: 1-5 (perintah membaca dan belajar)",ay:["96:1-5"],hd:[],um:"Mu'jam bekerja seperti indeks atau pencarian kata kunci pada basis data: menemukan informasi cepat lewat istilah.",so:"Literasi digital: memilih sumber tepercaya dan tidak menyebarkan potongan ayat tanpa konteks."}]}];

/* ========== DATA: isi materi per bab ========== */
var MAT=[{"tj":["Menjelaskan pengertian Al-Quran menurut para ulama","Menjelaskan nama-nama Al-Quran","Menunjukkan perilaku orang yang berpegang teguh kepada Al-Quran"],"s":[{"p":["Secara bahasa, ulama berbeda pendapat tentang asal kata Al-Quran. Al-Lihyani: dari kata kerja yang berarti membaca, jadi “bacaan”. Al-Asy’ari: berarti menggabungkan, karena surah, ayat, dan huruf saling bergandengan. Al-Farra’: berarti petunjuk, karena ayat-ayatnya saling membenarkan. Az-Zajjaj: berarti kumpulan kisah, perintah, larangan, dan inti sari kitab terdahulu. Asy-Syafi’i: nama asli yang tidak berasal dari kata apa pun, seperti Zabur, Taurat, dan Injil.","Abu Syuhbah menilai pendapat Al-Lihyani paling tepat dan paling masyhur. Perbedaan pendapat muncul karena sudut pandang berbeda dan kandungan Al-Quran yang sangat luas, sehingga justru saling melengkapi.","Secara istilah (Khudari Beik, Subkhi Saleh, Muhammad Abduh), unsur pengertian Al-Quran adalah:"],"r":["Al-Quran adalah kalamullah yang diturunkan kepada Nabi Muhammad saw., disampaikan mutawatir, dan membacanya ibadah.","Pendapat ulama tentang asal kata saling melengkapi."],"l":["Kalamullah berbahasa Arab","Diturunkan kepada Nabi Muhammad saw. melalui Jibril","Mengandung mukjizat","Disampaikan secara mutawatir","Ditulis dalam mushaf, dari Al-Fatihah sampai An-Nas","Membacanya bernilai ibadah","Terjaga kemurniannya lewat para penghafal"],"a":["75:17-18"]},{"p":["Imam Suyuthi dalam Al-Itqan menyebut Al-Quran memiliki 55 nama (pendapat lain 78). Nama-nama lain umumnya menunjukkan sifat, fungsi, atau indikator Al-Quran. Yang paling populer:"],"r":["Al-Quran punya banyak nama yang menggambarkan sifat dan fungsinya.","Empat nama populer lain: Al-Kitab, Al-Furqan, Az-Zikr, At-Tanzil."],"l":["Al-Quran: bacaan atau yang dibaca","Al-Kitab: kitab suci Allah, juga berarti yang ditulis","Al-Furqan: pembeda antara yang hak dan yang batil","Az-Zikr: pemberi peringatan","At-Tanzil: yang diturunkan melalui Jibril untuk seluruh manusia"],"a":["2:2","25:1","15:9"]},{"p":["Al-Quran adalah sumber pertama ajaran Islam. Isinya pedoman akidah (iman kepada Allah, malaikat, kitab, rasul, hari akhir, qada dan qadar), ibadah (salat, puasa, zakat, haji), dan budi pekerti.","Orang yang memahami Al-Quran menjalani hidup sesuai tuntunannya, baik sendirian maupun di tengah masyarakat homogen atau heterogen: berpikir, bersikap, dan bertindak menurut Al-Quran dengan etika yang dilandasi iman."],"r":["Setiap muslim wajib berpegang pada Al-Quran dalam akidah, ibadah, dan akhlak.","Tuntunan itu dijalankan baik saat sendiri maupun di tengah masyarakat."],"a":["7:204"]}]},{"tj":["Menghayati kebenaran penurunan Al-Quran","Memahami penurunan dan penulisan Al-Quran secara bertahap","Menganalisis sejarah penurunan Al-Quran"],"s":[{"p":["Secara majazi, turunnya Al-Quran berarti pemberitahuan dengan cara dan sarana yang dikehendaki Allah sehingga diketahui para malaikat di Lauh Mahfuz dan oleh Nabi Muhammad saw. di dalam hatinya yang suci.","Al-Quran turun selama 22 tahun 2 bulan 22 hari, dari malam 17 Ramadan sampai 9 Zulhijah saat haji wada’ (tahun 10 H). Wahyu pertama turun saat Nabi beribadah di Gua Hira melalui Jibril. Sebelumnya ada tanda-tanda berupa mimpi yang benar dan kecintaan Nabi untuk menyendiri (hadis Bukhari dari Aisyah). Proses menerima wahyu sangat berat, Nabi pun merasa takut hingga Jibril mengulangnya berkali-kali."],"r":["Wahyu pertama: Al-‘Alaq 1-5 di Gua Hira.","Al-Quran turun bertahap selama kurang lebih 22 tahun."],"a":["96:1-5"]},{"p":["Ulama berbeda pendapat tentang cara (kaifiyat) turunnya Al-Quran. Ada tiga pendapat:"],"r":["Ada tiga pendapat ulama tentang kaifiyat turunnya Al-Quran.","Pendapat tiga tingkat (Lauh Mahfuz, Baitul Izzah, dunia) ditolak Subkhi Saleh karena termasuk perkara gaib dan berlawanan dengan zahir Al-Quran."],"l":["Diturunkan sekaligus lengkap ke langit dunia pada malam Al-Qadr, lalu berangsur-angsur selama 20, 23, atau 25 tahun (berpegang pada riwayat At-Tabari dari Ibnu Abbas)","Diturunkan ke langit dunia setiap malam Al-Qadr tiap tahun, sebatas yang akan turun pada tahun itu","Permulaan turunnya pada malam Al-Qadr, lalu berangsur-angsur dalam berbagai waktu"]},{"p":["Penulisan dan pengumpulan Al-Quran melewati tiga fase.","Zaman Nabi: hafalan sahabat lebih berperan daripada tulisan yang masih terpisah. Ayat dihafal atau ditulis di pelepah kurma, kulit, batu cadas, atau tulang belikat unta; penghafalnya sangat banyak.","Zaman Abu Bakar: banyak penghafal gugur dalam perang Yamamah. Atas usul Umar, Abu Bakar menugaskan Zaid bin Tsabit menuliskan ulang catatan Al-Quran dalam satu mushaf, yang kemudian disimpan Abu Bakar, Umar, lalu Hafsah.","Zaman Utsman: catatan yang berbeda-beda dikhawatirkan menjadi fitnah. Utsman menugaskan Zaid, Abdullah bin Az-Zubair, Sa’id bin Al-‘Ash, dan Abdurrahman bin Al-Harits untuk menyalin dengan dialek Quraisy, lalu mengirimkannya ke berbagai negeri. Hasilnya persatuan, kesepakatan, dan terhindarnya perpecahan."],"r":["Tiga fase: zaman Nabi, Abu Bakar (dikumpulkan agar tidak hilang), dan Utsman (disatukan agar tidak berselisih bacaan).","Mushaf Utsman tetap terjaga hingga sekarang secara mutawatir."]}]},{"tj":["Menjelaskan bukti-bukti keotentikan Al-Quran","Membuktikan keotentikan dari segi keunikan redaksinya"],"s":[{"p":["Allah menjamin kemurnian Al-Quran sejak diturunkan hingga akhir zaman. Keindahan bahasa dan kandungannya menjadi bagian dari kemukjizatan yang menjaminnya.","Semua cetakan dan media penyimpan Al-Quran bersumber pada satu titik, yaitu mushaf yang dikodifikasi pada zaman Utsman, sehingga tulisan Al-Quran disebut rasm Utsmani. Mushaf tertua di Nusantara yang diklaim adalah karya Mas Khalifah Ibnu al-Habib al-Masfuh dari Banyuwangi (selesai sekitar 1806 M) dan kini berada di Perpustakaan Nasional Malaysia.","Berita viral tentang Al-Quran salah cetak mudah diketahui karena banyaknya penghafal. Sikap yang tepat: periksa dulu sebelum menyebarkan."],"r":["Keotentikan Al-Quran dijamin Allah.","Semua cetakan merujuk pada mushaf Utsman."],"a":["15:9"]},{"p":["Sejak dahulu orang yang menolak menuduh Al-Quran sebagai mantra tukang tenung, syair, atau karangan Nabi. Al-Quran menjawab dengan tiga tingkat tantangan:"],"r":["Tantangan tiga tingkat: seluruh Al-Quran, sepuluh surah, satu surah.","Hingga kini tidak ada yang mampu, sehingga Al-Quran terbukti wahyu Allah."],"l":["Membuat yang semisal seluruh Al-Quran (QS. At-Tur: 33-34; QS. Al-Isra: 88)","Membuat sepuluh surah semisalnya (QS. Hud: 13)","Membuat satu surah saja (QS. Al-Baqarah: 23)"],"a":["17:88","2:23"]},{"p":["Para penghafal Al-Quran tidak pernah putus generasi sejak pertama kali diturunkan. Inilah salah satu benteng penjaga kemurnian Al-Quran.","Cetakan Al-Quran terus dibuat, disimpan, diteliti, dan diperbarui, sejak masa wahyu disalin di batu, kulit, pelepah kurma, dan tulang. Penjagaan secara mutawatir berlangsung lintas zaman dalam berbagai media yang terus berkembang, di samping hafalan para penghafal."],"r":["Penghafal yang tak terputus adalah benteng keotentikan Al-Quran.","Cetakan terus diteliti dan diperbarui agar kemurniannya terjaga."],"a":[["Dan tidak mungkin Al-Quran ini dibuat-buat oleh selain Allah; tetapi (Al-Quran) membenarkan (kitab-kitab) yang sebelumnya dan menjelaskan hukum-hukum yang telah ditetapkannya, tidak ada keraguan di dalamnya, (diturunkan) dari Tuhan seluruh alam.","QS. Yunus: 37"]]}]},{"tj":["Menyajikan kemukjizatan Al-Quran","Mencintai Al-Quran","Menjelaskan dan memberi contoh kemukjizatan Al-Quran"],"s":[{"p":["Mukjizat berasal dari kata yang awalnya berarti melemahkan atau mengalahkan lawan. Manna’ Al-Qattan mendefinisikannya sebagai hal yang bertolak belakang dengan kebiasaan dan menang melawan tantangan. Kata ini hanya dipakai untuk hal luar biasa yang Allah berikan kepada para nabi dan rasul sebagai bukti kebenaran risalah mereka.","Mukjizat biasanya sesuai keunggulan zaman umatnya: zaman Nabi Musa adalah zaman tukang sihir, zaman Nabi Isa zaman kemajuan kedokteran, dan zaman Nabi Muhammad zaman keemasan sastra Arab. Suatu hal disebut mukjizat bila memenuhi kelima syarat:"],"r":["Mukjizat adalah keistimewaan dari Allah bagi nabi dan rasul sebagai bukti kenabian.","Harus memenuhi lima syarat."],"l":["Tidak sanggup dilakukan siapa pun selain Allah","Berlawanan dengan kebiasaan dan hukum alam (sunnatullah)","Dijadikan bukti oleh orang yang mengaku membawa risalah Ilahi","Terjadi bertepatan dengan pengakuan Nabi dan penolakan kaumnya","Tidak ada manusia atau jin yang dapat mengalahkannya"]},{"p":["Mukjizat hissi (kasat mata) dapat ditangkap panca indera dan dibatasi ruang dan waktu, artinya hanya diperlihatkan kepada umat dan masa tertentu. Contohnya tongkat Nabi Musa.","Mukjizat ma’nawi (tidak kasat mata) dicapai dengan akal dan mata batin, sehingga disebut juga mukjizat aqli atau rasional. Sifatnya universal dan abadi, berlaku untuk semua manusia sampai akhir zaman. Al-Quran adalah mukjizat ma’nawi.","Nabi Muhammad saw. juga diberi mukjizat hissi, misalnya air yang memancar dari jari-jari beliau saat sahabat kehausan dan terbelahnya bulan."],"r":["Hissi: terlihat indera, sementara. Ma’nawi: dipahami akal, abadi.","Al-Quran adalah mukjizat ma’nawi terbesar."]},{"p":["I’jaz Al-Quran adalah kokohnya kehebatan Al-Quran di hadapan kelemahan manusia dan jin yang tidak mampu membuat karya sehebat itu. Secara garis besar ada dua aspek.","Aspek bahasa (uslub): gaya bahasanya khas, bukan puisi, bukan prosa biasa, dan bukan syair. Keistimewaannya: keindahan lafaz dan susunan, dapat dirasakan semua lapisan, sesuai akal dan perasaan, beragam ungkapan untuk satu makna, memadukan global dan rinci, serta lugas. Umar bin Khattab masuk Islam setelah mendengar ayat-ayat awal surah Taha.","Aspek isi: berita gaib masa lalu (misalnya jasad Firaun yang diselamatkan, QS. Yunus: 92) dan masa depan (kemenangan Romawi atas Persia, QS. Ar-Rum: 1-3, yang terbukti sekitar sembilan tahun kemudian; kemenangan Badar, QS. Al-Qamar: 45; Fathu Makkah, QS. Al-Fath: 27); isyarat ilmu pengetahuan; dan hukum yang universal.","Catatan: pola jumlah huruf dan kata (misalnya angka 19) yang disebut dalam buku sering diperdebatkan cara menghitungnya, jadi periksa ulang sebelum dijadikan dalil."],"r":["Dua aspek i’jaz: gaya bahasa (uslub) dan isi.","Isi mencakup kabar gaib, isyarat ilmiah, dan hukum universal."],"a":["30:1-3"]},{"p":["Al-Quran menggambarkan mukjizat para nabi sebelum Nabi Muhammad saw.:"],"r":["Mukjizat para nabi bersifat hissi dan sesuai tantangan zamannya.","Semua terjadi atas izin Allah."],"l":["Nabi Nuh: membuat kapal besar menyelamatkan kaum beriman (QS. Hud: 37-38)","Nabi Ibrahim: tidak hangus dibakar api Namrud (QS. Al-Anbiya: 68-69)","Nabi Musa: tongkat menjadi ular dan memancarkan 12 mata air (QS. Al-A’raf: 107; Al-Baqarah: 60)","Nabi Dawud: melunakkan besi menjadi baju besi (QS. Saba: 10-11)","Nabi Sulaiman: memahami bahasa burung dan semut (QS. An-Naml: 16-18)","Nabi Isa: membuat burung dari tanah, menyembuhkan buta sejak lahir dan kusta, menghidupkan orang mati atas izin Allah (QS. Ali Imran: 49)"],"a":["21:68-69"]},{"p":["Al-Quran memuat isyarat ilmu pengetahuan yang tidak bertentangan dengan penemuan ilmiah yang berdasar penelitian. Buku menyebut, antara lain, perkawinan pada tiap benda, perbedaan sidik jari, berkurangnya oksigen di ketinggian, khasiat madu, asal kejadian alam semesta, dan penyerbukan oleh angin.","Contoh yang dibahas: QS. Al-Qiyamah: 3-4 tentang Allah menyusun kembali ujung jari dengan sempurna, yang dikaitkan dengan perbedaan sidik jari manusia.","Sikap yang tepat: baca sebagai bahan renungan. Teori ilmiah bisa berkembang dan penafsiran kaitan ayat dengan sains beragam di kalangan ulama."],"r":["Al-Quran memuat isyarat ilmiah yang mendorong manusia meneliti.","Kaitan ayat dan sains dibaca hati-hati karena teori sains dapat berkembang."],"a":["41:53"]}]},{"tj":["Menghayati kebenaran Al-Quran dalam setiap aspek kehidupan","Mengidentifikasi pokok-pokok isi Al-Quran","Menunjukkan ayat terkait pokok isi Al-Quran"],"s":[{"p":["Akidah berarti kepercayaan atau keyakinan, disebut juga keimanan. Secara istilah, akidah adalah keyakinan yang diyakini sepenuh hati, diucapkan dengan lisan, dan diwujudkan dalam amal perbuatan.","Inti akidah adalah tauhid, yakni keyakinan bahwa Allah Maha Esa. Seorang mukmin wajib meyakini enam rukun iman: iman kepada Allah, malaikat, kitab, rasul, hari akhir, serta qada dan qadar."],"r":["Inti akidah adalah tauhid.","Seorang mukmin wajib beriman kepada keenam rukun iman."],"a":["112:1-4",["Dan Tuhan kamu adalah Tuhan Yang Maha Esa, tidak ada tuhan selain Dia, Yang Maha Pengasih, Maha Penyayang.","QS. Al-Baqarah: 163"]]},{"p":["Ibadah berarti mengabdi dan tunduk sepenuhnya kepada Allah. Tujuan penciptaan jin dan manusia adalah beribadah kepada-Nya. Menurut tata caranya, ibadah ada dua: mahdhah (tata cara ditentukan jelas oleh syariat, seperti salat, puasa, zakat, haji) dan ghairu mahdhah (bersifat umum, seperti membaca Al-Quran, sedekah, atau bekerja mencari nafkah halal yang diniatkan ibadah).","Hubungan manusia dengan Allah disebut hablun minallah, dan hubungan antarmanusia (misalnya silaturahmi, jual beli, utang piutang) disebut hablun minannas atau muamalah. Keduanya diatur Al-Quran, misalnya perintah mencatat utang dalam QS. Al-Baqarah: 282."],"r":["Ibadah: mahdhah dan ghairu mahdhah.","Hablun minallah dan hablun minannas sama-sama diatur Al-Quran."],"a":["51:56",["Hanya kepada Engkaulah kami menyembah dan hanya kepada Engkaulah kami mohon pertolongan.","QS. Al-Fatihah: 5"]]},{"p":["Akhlak berarti perangai, tabiat, atau budi pekerti: sifat yang tertanam dalam jiwa dan muncul spontan dalam perilaku sehari-hari. Dalam bahasa Indonesia sepadan dengan etika atau moral.","Nabi saw. diutus untuk menyempurnakan akhlak mulia (HR. Ahmad). Beliau teladan pelaksanaan Al-Quran; ketika Aisyah ditanya tentang akhlak Rasul, beliau menjawab bahwa akhlak Nabi adalah Al-Quran."],"r":["Akhlak mulia adalah fondasi penting ajaran Islam.","Nabi Muhammad saw. adalah teladan akhlak yang mencerminkan Al-Quran."],"a":["68:4","33:21","ahmad8952"]},{"p":["Al-Quran memuat kaidah dan ketentuan dasar agar kehidupan manusia adil, aman, tenteram, teratur, dan sejahtera di dunia dan akhirat. Ketentuannya ada yang global (mujmal) dan ada yang rinci (tafshil).","Contoh bidang hukum dalam Al-Quran:"],"r":["Hukum Islam bersumber utama dari Al-Quran.","Ketentuannya mencakup perkawinan, waris, perjanjian, pidana, perang, dan hubungan antarbangsa."],"l":["Perkawinan (QS. Al-Baqarah: 221; An-Nisa: 22-24; An-Nur: 2)","Waris (QS. An-Nisa: 7-12 dan 176)","Perjanjian (QS. Al-Baqarah: 279, 280, 282)","Pidana (QS. Al-Baqarah: 178; Al-Maidah: 38)","Perang (QS. Al-Baqarah: 190-193)","Hubungan antarbangsa (QS. Al-Hujurat: 13)"],"a":[["Wahai orang-orang yang beriman! Sesungguhnya minuman keras, berjudi, (berkurban untuk) berhala, dan mengundi nasib dengan anak panah, adalah perbuatan keji dan termasuk perbuatan setan. Maka jauhilah (perbuatan-perbuatan) itu agar kamu beruntung.","QS. Al-Maidah: 90"]]},{"p":["Kisah umat terdahulu dalam Al-Quran bukan sekadar cerita atau dongeng, melainkan ‘ibrah (pelajaran). Dengan berkaca pada kisah itu, umat Islam meneladani umat yang taat kepada Allah dan menjauhi maksiat seperti yang dilakukan sebagian umat terdahulu."],"r":["Kisah dalam Al-Quran berfungsi sebagai ‘ibrah.","Contoh kisah: kaum Nuh, ‘Ad, dan Samud (QS. Al-Furqan: 37-39)."],"a":[["Sungguh, pada kisah-kisah mereka itu terdapat pengajaran bagi orang yang mempunyai akal. (Al-Quran) itu bukanlah cerita yang dibuat-buat, tetapi membenarkan (kitab-kitab) yang sebelumnya, menjelaskan segala sesuatu, dan (sebagai) petunjuk dan rahmat bagi orang-orang yang beriman.","QS. Yusuf: 111"]]},{"p":["Al-Quran menekankan pentingnya ilmu dan teknologi untuk meningkatkan peradaban. Hal ini sudah terisyarat pada wahyu pertama yang diawali perintah membaca. Isyarat ilmu mencakup kedokteran, farmasi, pertanian, matematika, fisika, kimia, biologi, anatomi, dan lain-lain.","Dalam sejarah, umat Islam melahirkan cendekiawan seperti Ibnu Rusyd, Al-Farabi, Ibnu Sina, Ibnu Miskawaih, dan Al-Khawarizmi, yang penemuannya kemudian dikembangkan ilmuwan Barat.","Orang yang berpedoman pada Al-Quran hatinya lembut dan lapang. Nabi saw. bersabda bahwa sebaik-baik manusia adalah yang belajar Al-Quran dan mengajarkannya (HR. Bukhari dari Utsman bin Affan)."],"r":["Al-Quran mendorong manusia membaca, belajar, dan meneliti.","Mengamalkan Al-Quran menumbuhkan hikmah dan kebijaksanaan."],"a":["58:11"]}]},{"tj":["Mengidentifikasi kebenaran Al-Quran berlaku sepanjang zaman","Menganalisis struktur ayat dan surah","Menggunakan kitab indeks atau mu’jam"],"s":[{"p":["Al-Quran terdiri atas 114 surah dan 30 juz. Jumlah ayat 6.236 menurut riwayat Hafs (6.262 menurut riwayat Ad-Dur, 6.214 menurut Warsy); secara tradisional sering disebut 6.666. Juz memudahkan khatam dalam 30 hari.","Manzil membagi Al-Quran menjadi 7 bagian agar khatam dalam seminggu:"],"r":["114 surah, 30 juz, dan 7 manzil.","Pembagian dibuat untuk memudahkan membaca dan mempelajari Al-Quran."],"l":["Manzil 1: Al-Fatihah sampai An-Nisa","Manzil 2: Al-Maidah sampai At-Taubah","Manzil 3: Yunus sampai An-Nahl","Manzil 4: Al-Isra sampai Al-Furqan","Manzil 5: Asy-Syu’ara sampai Yasin","Manzil 6: Ash-Shaffat sampai Al-Hujurat","Manzil 7: Qaf sampai An-Nas"]},{"p":["Ayat yang diterima sebelum hijrah disebut Makkiyah, dan yang setelah hijrah disebut Madaniyah, meskipun turun di Makkah (misalnya saat haji wada’). Pembagian berdasar waktu ini dianggap lebih tepat. Sebagian ulama memakai tempat turunnya.","Ciri Makkiyah: surah dan ayat pendek; membahas prinsip iman dan akhlak; ada kata kalla; memuat kisah nabi dan umat terdahulu; cenderung puitis; contoh Al-Ikhlas, An-Nas, Al-Falaq.","Ciri Madaniyah: surah dan ayat panjang; izin dan hukum perang; rincian hukum ibadah, sipil, sosial, dan hubungan antarnegara; menyebut kaum munafik dan ahli kitab; ungkapan tenang dan banyak argumentasi; contoh Al-Baqarah dan Ali Imran."],"r":["Makkiyah: sebelum hijrah, fokus iman dan akhlak.","Madaniyah: setelah hijrah, fokus hukum dan tatanan masyarakat."]},{"p":["Maqra’ adalah sub pembahasan dalam Al-Quran, pada mushaf lama biasanya ditandai huruf ain di tepi halaman. Disebut juga ruku’ karena dahulu dibaca setelah Al-Fatihah sebelum rukuk dalam salat.","Setiap maqra’ biasanya berisi satu sub pembahasan, misalnya kisah Nabi Musa, kisah Nabi Yusuf, atau tentang akhirat. Maqra’ juga digunakan qari dan qariah dalam Musabaqah Tilawatil Quran (MTQ)."],"r":["Maqra’ atau ruku’ adalah bagian pembahasan tertentu dalam surah.","Digunakan juga dalam MTQ dan acara keagamaan."]},{"p":["Lafaz Bismillahirrahmanirrahim terdapat di pembuka seluruh surah kecuali At-Taubah. Walau demikian, jumlahnya tetap 114 karena dalam surah An-Naml disebut dua kali: di pembuka surah dan pada ayat 30 yang berkaitan dengan surat Nabi Sulaiman kepada Ratu Saba."],"r":["Basmalah membuka seluruh surah kecuali At-Taubah.","Jumlahnya 114 karena disebut dua kali dalam An-Naml."]},{"p":["Untuk mencari ayat yang berkaitan dengan istilah tertentu digunakan kamus khusus Al-Quran yang disebut mu’jam. Kamus ini memakai daftar istilah untuk mengumpulkan pembahasan tertentu.","Kitab mu’jam yang terkenal: Al-Mu’jam Al-Mufahras li Alfazh Al-Quran Al-Karim karya Muhammad Fuad Abdul Baqi, dan Al-Mu’jam Al-Mufahras li Ma’ani Al-Quran Al-Karim karya Muhammad Bassam Rusydi Az-Zain."],"r":["Mu’jam membantu menemukan ayat berdasarkan kata atau tema.","Gunakan sumber yang jelas dan cocokkan dengan penjelasan guru."],"a":["96:1-5"]}]}];

/* ========== DATA: teks ayat Al-Quran ========== */
var AYAT={"10:92": {"ar": "فَٱلۡيَوۡمَ نُنَجِّيكَ بِبَدَنِكَ لِتَكُونَ لِمَنۡ خَلۡفَكَ ءَايَةٗۚ وَإِنَّ كَثِيرٗا مِّنَ ٱلنَّاسِ عَنۡ ءَايَٰتِنَا لَغَٰفِلُونَ ﴿٩٢﴾", "id": "(Maka pada hari ini Kami selamatkan jasadmu392) agar engkau dapat menjadi pelajaran bagi orang-orang yang datang setelahmu, tetapi kebanyakan manusia tidak mengindahkan tanda-tanda (kekuasaan) Kami", "lb": "QS. Yunus: 92 · terjemah Kemenag RI"}, "112:1-4": {"ar": "قُلۡ هُوَ ٱللَّهُ أَحَدٌ ﴿١﴾ ٱللَّهُ ٱلصَّمَدُ ﴿٢﴾ لَمۡ يَلِدۡ وَلَمۡ يُولَدۡ ﴿٣﴾ وَلَمۡ يَكُن لَّهُۥ كُفُوًا أَحَدُۢ ﴿٤﴾", "id": "(1) Katakanlah (Muhammad), \"Dialah Allah, Yang Maha Esa (2) Allah tempat meminta segala sesuatu (3) (Allah) tidak beranak dan tidak pula diperanakkan (4) Dan tidak ada sesuatu yang setara dengan Dia", "lb": "QS. Al-Ikhlas: 1-4 · terjemah Kemenag RI"}, "11:13": {"ar": "أَمۡ يَقُولُونَ ٱفۡتَرَىٰهُۖ قُلۡ فَأۡتُواْ بِعَشۡرِ سُوَرٖ مِّثۡلِهِۦ مُفۡتَرَيَٰتٖ وَٱدۡعُواْ مَنِ ٱسۡتَطَعۡتُم مِّن دُونِ ٱللَّهِ إِن كُنتُمۡ صَٰدِقِينَ ﴿١٣﴾", "id": "Bahkan mereka mengatakan, \"Dia (Muhammad) telah membuat-buat Alquran itu.\" Katakanlah, \"(Kalau demikian), datangkanlah sepuluh surah semisal dengannya (Alquran) yang dibuat-buat, dan ajaklah siapa saja di antara kamu yang sanggup selain Allah, jika kamu orang-orang yang benar", "lb": "QS. Hud: 13 · terjemah Kemenag RI"}, "11:37-38": {"ar": "وَٱصۡنَعِ ٱلۡفُلۡكَ بِأَعۡيُنِنَا وَوَحۡيِنَا وَلَا تُخَٰطِبۡنِي فِي ٱلَّذِينَ ظَلَمُوٓاْ إِنَّهُم مُّغۡرَقُونَ ﴿٣٧﴾ وَيَصۡنَعُ ٱلۡفُلۡكَ وَكُلَّمَا مَرَّ عَلَيۡهِ مَلَأٞ مِّن قَوۡمِهِۦ سَخِرُواْ مِنۡهُۚ قَالَ إِن تَسۡخَرُواْ مِنَّا فَإِنَّا نَسۡخَرُ مِنكُمۡ كَمَا تَسۡخَرُونَ ﴿٣٨﴾", "id": "(37) Dan buatlah kapal itu dengan pengawasan dan petunjuk wahyu Kami, dan janganlah engkau bicara dengan Aku tentang orang-orang yang zalim. Sesungguhnya mereka itu akan ditenggelamkan (38) Dan mulailah dia (Nuh) membuat kapal. Setiap kali pemimpin kaumnya berjalan melewatinya, mereka mengejeknya. Dia (Nuh) berkata, \"Jika kamu mengejek kami, maka kami (pun) akan mengejekmu sebagaimana kamu mengejek (kami)", "lb": "QS. Hud: 37-38 · terjemah Kemenag RI"}, "15:9": {"ar": "إِنَّا نَحۡنُ نَزَّلۡنَا ٱلذِّكۡرَ وَإِنَّا لَهُۥ لَحَٰفِظُونَ ﴿٩﴾", "id": "Sesungguhnya Kamilah yang menurunkan Alquran, dan pasti Kami (pula) yang memeliharanya", "lb": "QS. Al-Hijr: 9 · terjemah Kemenag RI"}, "17:88": {"ar": "قُل لَّئِنِ ٱجۡتَمَعَتِ ٱلۡإِنسُ وَٱلۡجِنُّ عَلَىٰٓ أَن يَأۡتُواْ بِمِثۡلِ هَٰذَا ٱلۡقُرۡءَانِ لَا يَأۡتُونَ بِمِثۡلِهِۦ وَلَوۡ كَانَ بَعۡضُهُمۡ لِبَعۡضٖ ظَهِيرٗا ﴿٨٨﴾", "id": "Katakanlah, \"Sesungguhnya jika manusia dan jin berkumpul untuk membuat yang serupa (dengan) Alquran ini, mereka tidak akan dapat membuat yang serupa dengannya, sekali pun mereka saling membantu satu sama lain", "lb": "QS. Al-Isra: 88 · terjemah Kemenag RI"}, "21:30": {"ar": "أَوَلَمۡ يَرَ ٱلَّذِينَ كَفَرُوٓاْ أَنَّ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ كَانَتَا رَتۡقٗا فَفَتَقۡنَٰهُمَاۖ وَجَعَلۡنَا مِنَ ٱلۡمَآءِ كُلَّ شَيۡءٍ حَيٍّۚ أَفَلَا يُؤۡمِنُونَ ﴿٣٠﴾", "id": "Dan apakah orang-orang kafir tidak mengetahui bahwa langit dan bumi keduanya dahulu menyatu, kemudian Kami pisahkan antara keduanya; dan Kami jadikan segala sesuatu yang hidup berasal dari air; maka mengapa mereka tidak beriman", "lb": "QS. Al-Anbya: 30 · terjemah Kemenag RI"}, "21:68-69": {"ar": "قَالُواْ حَرِّقُوهُ وَٱنصُرُوٓاْ ءَالِهَتَكُمۡ إِن كُنتُمۡ فَٰعِلِينَ ﴿٦٨﴾ قُلۡنَا يَٰنَارُ كُونِي بَرۡدٗا وَسَلَٰمًا عَلَىٰٓ إِبۡرَٰهِيمَ ﴿٦٩﴾", "id": "(68) Mereka berkata, \"Bakarlah dia dan bantulah tuhan-tuhan kamu, jika kamu benar-benar hendak berbuat (69) Kami (Allah) berfirman, \"Wahai api! Jadilah kamu dingin, dan penyelamat bagi Ibrahim", "lb": "QS. Al-Anbya: 68-69 · terjemah Kemenag RI"}, "25:1": {"ar": "تَبَارَكَ ٱلَّذِي نَزَّلَ ٱلۡفُرۡقَانَ عَلَىٰ عَبۡدِهِۦ لِيَكُونَ لِلۡعَٰلَمِينَ نَذِيرًا ﴿١﴾", "id": "Mahasuci Allah yang telah menurunkan Furqan (Alquran) kepada hamba-Nya (Muhammad), agar dia menjadi pemberi peringatan kepada seluruh alam (jin dan manusia)", "lb": "QS. Al-Furqan: 1 · terjemah Kemenag RI"}, "26:192": {"ar": "وَإِنَّهُۥ لَتَنزِيلُ رَبِّ ٱلۡعَٰلَمِينَ ﴿١٩٢﴾", "id": "Dan sungguh, (Alquran) ini benar-benar diturunkan oleh Tuhan seluruh alam", "lb": "QS. Ash-Shu'ara: 192 · terjemah Kemenag RI"}, "2:185": {"ar": "شَهۡرُ رَمَضَانَ ٱلَّذِيٓ أُنزِلَ فِيهِ ٱلۡقُرۡءَانُ هُدٗى لِّلنَّاسِ وَبَيِّنَٰتٖ مِّنَ ٱلۡهُدَىٰ وَٱلۡفُرۡقَانِۚ فَمَن شَهِدَ مِنكُمُ ٱلشَّهۡرَ فَلۡيَصُمۡهُۖ وَمَن كَانَ مَرِيضًا أَوۡ عَلَىٰ سَفَرٖ فَعِدَّةٞ مِّنۡ أَيَّامٍ أُخَرَۗ يُرِيدُ ٱللَّهُ بِكُمُ ٱلۡيُسۡرَ وَلَا يُرِيدُ بِكُمُ ٱلۡعُسۡرَ وَلِتُكۡمِلُواْ ٱلۡعِدَّةَ وَلِتُكَبِّرُواْ ٱللَّهَ عَلَىٰ مَا هَدَىٰكُمۡ وَلَعَلَّكُمۡ تَشۡكُرُونَ ﴿١٨٥﴾", "id": "Bulan Ramadan adalah (bulan) yang di dalamnya diturunkan Alquran, sebagai petunjuk bagi manusia dan penjelasan-penjelasan mengenai petunjuk itu dan pembeda (antara yang benar dan yang batil). Karena itu, barang siapa di antara kamu mendapati bulan itu, maka berpuasalah. Dan barang siapa sakit atau dalam perjalanan (dia tidak berpuasa), maka (wajib menggantinya), sebanyak hari yang ditinggalkannya, pada hari-hari yang lain. Allah menghendaki kemudahan bagimu, dan tidak menghendaki kesukaran bagimu. Hendaklah kamu mencukupkan bilangannya dan mengagungkan Allah atas petunjuk-Nya yang diberikan kepadamu, agar kamu bersyukur", "lb": "QS. Al-Baqarah: 185 · terjemah Kemenag RI"}, "2:2": {"ar": "ذَٰلِكَ ٱلۡكِتَٰبُ لَا رَيۡبَۛ فِيهِۛ هُدٗى لِّلۡمُتَّقِينَ ﴿٢﴾", "id": "Kitab (Alquran) ini tidak ada keraguan padanya; petunjuk bagi mereka yang bertakwa", "lb": "QS. Al-Baqarah: 2 · terjemah Kemenag RI"}, "2:23": {"ar": "وَإِن كُنتُمۡ فِي رَيۡبٖ مِّمَّا نَزَّلۡنَا عَلَىٰ عَبۡدِنَا فَأۡتُواْ بِسُورَةٖ مِّن مِّثۡلِهِۦ وَٱدۡعُواْ شُهَدَآءَكُم مِّن دُونِ ٱللَّهِ إِن كُنتُمۡ صَٰدِقِينَ ﴿٢٣﴾", "id": "Dan jika kamu meragukan (Alquran) yang kami turunkan kepada hamba Kami (Muhammad), maka buatlah satu surah semisal dengannya dan ajaklah penolong-penolongmu selain Allah, jika kamu orang-orang yang benar", "lb": "QS. Al-Baqarah: 23 · terjemah Kemenag RI"}, "2:282": {"ar": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِذَا تَدَايَنتُم بِدَيۡنٍ إِلَىٰٓ أَجَلٖ مُّسَمّٗى فَٱكۡتُبُوهُۚ وَلۡيَكۡتُب بَّيۡنَكُمۡ كَاتِبُۢ بِٱلۡعَدۡلِۚ وَلَا يَأۡبَ كَاتِبٌ أَن يَكۡتُبَ كَمَا عَلَّمَهُ ٱللَّهُۚ فَلۡيَكۡتُبۡ وَلۡيُمۡلِلِ ٱلَّذِي عَلَيۡهِ ٱلۡحَقُّ وَلۡيَتَّقِ ٱللَّهَ رَبَّهُۥ وَلَا يَبۡخَسۡ مِنۡهُ شَيۡـٔٗاۚ فَإِن كَانَ ٱلَّذِي عَلَيۡهِ ٱلۡحَقُّ سَفِيهًا أَوۡ ضَعِيفًا أَوۡ لَا يَسۡتَطِيعُ أَن يُمِلَّ هُوَ فَلۡيُمۡلِلۡ وَلِيُّهُۥ بِٱلۡعَدۡلِۚ وَٱسۡتَشۡهِدُواْ شَهِيدَيۡنِ مِن رِّجَالِكُمۡۖ فَإِن لَّمۡ يَكُونَا رَجُلَيۡنِ فَرَجُلٞ وَٱمۡرَأَتَانِ مِمَّن تَرۡضَوۡنَ مِنَ ٱلشُّهَدَآءِ أَن تَضِلَّ إِحۡدَىٰهُمَا فَتُذَكِّرَ إِحۡدَىٰهُمَا ٱلۡأُخۡرَىٰۚ وَلَا يَأۡبَ ٱلشُّهَدَآءُ إِذَا مَا دُعُواْۚ وَلَا تَسۡـَٔمُوٓاْ أَن تَكۡتُبُوهُ صَغِيرًا أَوۡ كَبِيرًا إِلَىٰٓ أَجَلِهِۦۚ ذَٰلِكُمۡ أَقۡسَطُ عِندَ ٱللَّهِ وَأَقۡوَمُ لِلشَّهَٰدَةِ وَأَدۡنَىٰٓ أَلَّا تَرۡتَابُوٓاْ إِلَّآ أَن تَكُونَ تِجَٰرَةً حَاضِرَةٗ تُدِيرُونَهَا بَيۡنَكُمۡ فَلَيۡسَ عَلَيۡكُمۡ جُنَاحٌ أَلَّا تَكۡتُبُوهَاۗ وَأَشۡهِدُوٓاْ إِذَا تَبَايَعۡتُمۡۚ وَلَا يُضَآرَّ كَاتِبٞ وَلَا شَهِيدٞۚ وَإِن تَفۡعَلُواْ فَإِنَّهُۥ فُسُوقُۢ بِكُمۡۗ وَٱتَّقُواْ ٱللَّهَۖ وَيُعَلِّمُكُمُ ٱللَّهُۗ وَٱللَّهُ بِكُلِّ شَيۡءٍ عَلِيمٞ ﴿٢٨٢﴾", "id": "Wahai orang-orang yang beriman! Apabila kamu melakukan utang piutang untuk waktu yang ditentukan, hendaklah kamu menuliskannya. Dan hendaklah seorang penulis di antara kamu menuliskannya dengan benar. Janganlah penulis menolak untuk menuliskannya sebagaimana Allah telah mengajarkan kepadanya, maka hendaklah dia menuliskan. Dan hendaklah orang yang berutang itu mendiktekan, dan hendaklah dia bertakwa kepada Allah, Tuhannya, dan janganlah dia mengurangi sedikitpun daripadanya. Jika yang berutang itu orang yang kurang akalnya atau lemah (keadaannya), atau tidak mampu mendiktekan sendiri, maka hendaklah walinya mendiktekannya dengan benar. Dan persaksikanlah dengan dua orang saksi laki-laki diantara kamu. Jika tidak ada (saksi) dua orang laki-laki, maka (boleh) seorang laki-laki dan dua orang perempuan diantara orang-orang yang kamu sukai dari para saksi (yang ada), agar jika yang seorang lupa maka yang lain mengingatkannya. Dan janganlah saksi-saksi itu menolak apabila dipanggil. Dan janganlah kamu bosan menuliskannya, untuk batas waktunya baik (utang itu) kecil maupun besar. Yang demikian itu, lebih adil di sisi Allah, lebih dapat menguatkan kesaksian, dan lebih mendekatkan kamu kepada ketidakraguan, kecuali jika hal itu merupakan perdagangan tunai yang kamu jalankan diantara kamu, maka tidak ada dosa bagi kamu jika kamu tidak menuliskannya. Dan ambillah saksi apabila kamu berjual beli, dan janganlah menulis dipersulit dan begitu juga saksi. Jika kamu lakukan (yang demikian), maka sungguh, hal itu suatu kefasikan pada kamu. Dan bertakwalah kepada Allah, Allah memberikan pengajaran kepadamu, dan Allah Maha Mengetahui segala sesuatu", "lb": "QS. Al-Baqarah: 282 · terjemah Kemenag RI"}, "30:1-3": {"ar": "الٓمٓ ﴿١﴾ غُلِبَتِ ٱلرُّومُ ﴿٢﴾ فِيٓ أَدۡنَى ٱلۡأَرۡضِ وَهُم مِّنۢ بَعۡدِ غَلَبِهِمۡ سَيَغۡلِبُونَ ﴿٣﴾", "id": "(1) Alif Lām Mīm (2) Bangsa Romawi telah dikalahkan (3) (di negeri yang terdekat633) dan mereka setelah kekalahannya itu akan menang", "lb": "QS. Ar-Rum: 1-3 · terjemah Kemenag RI"}, "30:41": {"ar": "ظَهَرَ ٱلۡفَسَادُ فِي ٱلۡبَرِّ وَٱلۡبَحۡرِ بِمَا كَسَبَتۡ أَيۡدِي ٱلنَّاسِ لِيُذِيقَهُم بَعۡضَ ٱلَّذِي عَمِلُواْ لَعَلَّهُمۡ يَرۡجِعُونَ ﴿٤١﴾", "id": "Telah tampak kerusakan di darat dan di laut disebabkan karena perbuatan tangan manusia; Allah menghendaki agar mereka merasakan sebagian dari (akibat) perbuatan mereka, agar mereka kembali (ke jalan yang benar)", "lb": "QS. Ar-Rum: 41 · terjemah Kemenag RI"}, "33:21": {"ar": "لَّقَدۡ كَانَ لَكُمۡ فِي رَسُولِ ٱللَّهِ أُسۡوَةٌ حَسَنَةٞ لِّمَن كَانَ يَرۡجُواْ ٱللَّهَ وَٱلۡيَوۡمَ ٱلۡأٓخِرَ وَذَكَرَ ٱللَّهَ كَثِيرٗا ﴿٢١﴾", "id": "Sungguh, telah ada pada (diri) Rasulullah itu suri teladan yang baik bagimu (yaitu) bagi orang yang mengharap (rahmat) Allah dan (kedatangan) hari Kiamat dan yang banyak mengingat Allah", "lb": "QS. Al-Ahzab: 21 · terjemah Kemenag RI"}, "41:53": {"ar": "سَنُرِيهِمۡ ءَايَٰتِنَا فِي ٱلۡأٓفَاقِ وَفِيٓ أَنفُسِهِمۡ حَتَّىٰ يَتَبَيَّنَ لَهُمۡ أَنَّهُ ٱلۡحَقُّۗ أَوَلَمۡ يَكۡفِ بِرَبِّكَ أَنَّهُۥ عَلَىٰ كُلِّ شَيۡءٖ شَهِيدٌ ﴿٥٣﴾", "id": "Kami akan memperlihatkan kepada mereka tanda-tanda (kebesaran) Kami di segenap penjuru dan pada diri mereka sendiri, sehingga jelaslah bagi mereka bahwa Alquran itu adalah benar. Tidak cukupkah (bagi kamu) bahwa Tuhanmu menjadi saksi atas segala sesuatu", "lb": "QS. Fussilat: 53 · terjemah Kemenag RI"}, "49:13": {"ar": "يَـٰٓأَيُّهَا ٱلنَّاسُ إِنَّا خَلَقۡنَٰكُم مِّن ذَكَرٖ وَأُنثَىٰ وَجَعَلۡنَٰكُمۡ شُعُوبٗا وَقَبَآئِلَ لِتَعَارَفُوٓاْۚ إِنَّ أَكۡرَمَكُمۡ عِندَ ٱللَّهِ أَتۡقَىٰكُمۡۚ إِنَّ ٱللَّهَ عَلِيمٌ خَبِيرٞ ﴿١٣﴾", "id": "Wahai manusia! Sungguh, Kami telah menciptakan kamu dari seorang laki-laki dan seorang perempuan, kemudian Kami jadikan kamu berbangsa-bangsa dan bersuku-suku agar kamu saling mengenal. Sungguh, yang paling mulia di antara kamu di sisi Allah ialah orang yang paling bertakwa. Sungguh, Allah Maha Mengetahui, Mahateliti", "lb": "QS. Al-Hujurat: 13 · terjemah Kemenag RI"}, "49:6": {"ar": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِن جَآءَكُمۡ فَاسِقُۢ بِنَبَإٖ فَتَبَيَّنُوٓاْ أَن تُصِيبُواْ قَوۡمَۢا بِجَهَٰلَةٖ فَتُصۡبِحُواْ عَلَىٰ مَا فَعَلۡتُمۡ نَٰدِمِينَ ﴿٦﴾", "id": "Wahai orang-orang yang beriman! Jika seorang yang fasik datang kepadamu membawa suatu berita, maka telitilah kebenarannya, agar kamu tidak mencelakakan suatu kaum karena kebodohan (kecerobohan), yang akhirnya kamu menyesali perbuatanmu itu", "lb": "QS. Al-Hujurat: 6 · terjemah Kemenag RI"}, "51:47": {"ar": "وَٱلسَّمَآءَ بَنَيۡنَٰهَا بِأَيۡيْدٖ وَإِنَّا لَمُوسِعُونَ ﴿٤٧﴾", "id": "Dan langit Kami bangun dengan kekuasaan (Kami), dan Kami benar-benar meluaskannya", "lb": "QS. Adh-Dhariyat: 47 · terjemah Kemenag RI"}, "51:56": {"ar": "وَمَا خَلَقۡتُ ٱلۡجِنَّ وَٱلۡإِنسَ إِلَّا لِيَعۡبُدُونِ ﴿٥٦﴾", "id": "Aku tidak menciptakan jin dan manusia melainkan agar mereka beribadah kepada-Ku", "lb": "QS. Adh-Dhariyat: 56 · terjemah Kemenag RI"}, "52:33-34": {"ar": "أَمۡ يَقُولُونَ تَقَوَّلَهُۥۚ بَل لَّا يُؤۡمِنُونَ ﴿٣٣﴾ فَلۡيَأۡتُواْ بِحَدِيثٖ مِّثۡلِهِۦٓ إِن كَانُواْ صَٰدِقِينَ ﴿٣٤﴾", "id": "(33) Ataukah mereka berkata, \"Dia (Muhammad) mereka-rekanya.\" Tidak! Merekalah yang tidak beriman (34) Maka cobalah mereka membuat yang semisal dengannya (Alquran) jika mereka orang-orang yang benar", "lb": "QS. At-Tur: 33-34 · terjemah Kemenag RI"}, "54:17": {"ar": "وَلَقَدۡ يَسَّرۡنَا ٱلۡقُرۡءَانَ لِلذِّكۡرِ فَهَلۡ مِن مُّدَّكِرٖ ﴿١٧﴾", "id": "Dan sungguh, telah Kami mudahkan Alquran untuk peringatan, maka adakah orang yang mau mengambil pelajaran", "lb": "QS. Al-Qamar: 17 · terjemah Kemenag RI"}, "58:11": {"ar": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِذَا قِيلَ لَكُمۡ تَفَسَّحُواْ فِي ٱلۡمَجَٰلِسِ فَٱفۡسَحُواْ يَفۡسَحِ ٱللَّهُ لَكُمۡۖ وَإِذَا قِيلَ ٱنشُزُواْ فَٱنشُزُواْ يَرۡفَعِ ٱللَّهُ ٱلَّذِينَ ءَامَنُواْ مِنكُمۡ وَٱلَّذِينَ أُوتُواْ ٱلۡعِلۡمَ دَرَجَٰتٖۚ وَٱللَّهُ بِمَا تَعۡمَلُونَ خَبِيرٞ ﴿١١﴾", "id": "Wahai orang-orang yang beriman! Apabila dikatakan kepadamu, \"Berilah kelapangan di dalam majelis-majelis,\" maka lapangkanlah, niscaya Allah akan memberi kelapangan untukmu. Dan apabila dikatakan, \"Berdirilah kamu,\" maka berdirilah, niscaya Allah akan mengangkat (derajat) orang-orang yang beriman di antaramu dan orang-orang yang diberi ilmu beberapa derajat. Dan Allah Mahateliti atas apa yang kamu kerjakan", "lb": "QS. Al-Mujadila: 11 · terjemah Kemenag RI"}, "68:4": {"ar": "وَإِنَّكَ لَعَلَىٰ خُلُقٍ عَظِيمٖ ﴿٤﴾", "id": "Dan sesungguhnya engkau benar-benar, berbudi pekerti yang luhur", "lb": "QS. Al-Qalam: 4 · terjemah Kemenag RI"}, "6:125": {"ar": "فَمَن يُرِدِ ٱللَّهُ أَن يَهۡدِيَهُۥ يَشۡرَحۡ صَدۡرَهُۥ لِلۡإِسۡلَٰمِۖ وَمَن يُرِدۡ أَن يُضِلَّهُۥ يَجۡعَلۡ صَدۡرَهُۥ ضَيِّقًا حَرَجٗا كَأَنَّمَا يَصَّعَّدُ فِي ٱلسَّمَآءِۚ كَذَٰلِكَ يَجۡعَلُ ٱللَّهُ ٱلرِّجۡسَ عَلَى ٱلَّذِينَ لَا يُؤۡمِنُونَ ﴿١٢٥﴾", "id": "Barang siapa yang dikehendaki Allah akan mendapat hidayah (petunjuk), Dia akan membukakan dadanya untuk (menerima) Islam. Dan barang siapa dikehendaki-Nya menjadi sesat, Dia jadikan dadanya sempit dan sesak, seakan-akan dia (sedang) mendaki ke langit. Demikianlah Allah menimpakan siksa kepada orang-orang yang tidak beriman", "lb": "QS. Al-An'am: 125 · terjemah Kemenag RI"}, "75:17-18": {"ar": "إِنَّ عَلَيۡنَا جَمۡعَهُۥ وَقُرۡءَانَهُۥ ﴿١٧﴾ فَإِذَا قَرَأۡنَٰهُ فَٱتَّبِعۡ قُرۡءَانَهُۥ ﴿١٨﴾", "id": "(17) Sesungguhnya Kami yang akan mengumpulkannya (di dadamu) dan membacakannya (18) Apabila Kami telah selesai membacakannya maka ikutilah bacaannya itu", "lb": "QS. Al-Qiyamah: 17-18 · terjemah Kemenag RI"}, "75:3-4": {"ar": "أَيَحۡسَبُ ٱلۡإِنسَٰنُ أَلَّن نَّجۡمَعَ عِظَامَهُۥ ﴿٣﴾ بَلَىٰ قَٰدِرِينَ عَلَىٰٓ أَن نُّسَوِّيَ بَنَانَهُۥ ﴿٤﴾", "id": "(3) Apakah manusia mengira, bahwa Kami tidak akan mengumpulkan (kembali) tulang belulangnya (4) (Bahkan) Kami mampu menyusun (kembali) jari jemarinya dengan sempurna", "lb": "QS. Al-Qiyamah: 3-4 · terjemah Kemenag RI"}, "7:107": {"ar": "فَأَلۡقَىٰ عَصَاهُ فَإِذَا هِيَ ثُعۡبَانٞ مُّبِينٞ ﴿١٠٧﴾", "id": "Lalu (Musa) melemparkan tongkatnya, tiba-tiba tongkat itu menjadi ular yang sebenarnya", "lb": "QS. Al-A'raf: 107 · terjemah Kemenag RI"}, "7:204": {"ar": "وَإِذَا قُرِئَ ٱلۡقُرۡءَانُ فَٱسۡتَمِعُواْ لَهُۥ وَأَنصِتُواْ لَعَلَّكُمۡ تُرۡحَمُونَ ﴿٢٠٤﴾", "id": "Dan apabila dibacakan Alquran, maka dengarkanlah dan diamlah, agar kamu mendapat rahmat", "lb": "QS. Al-A'raf: 204 · terjemah Kemenag RI"}, "96:1-5": {"ar": "ٱقۡرَأۡ بِٱسۡمِ رَبِّكَ ٱلَّذِي خَلَقَ ﴿١﴾ خَلَقَ ٱلۡإِنسَٰنَ مِنۡ عَلَقٍ ﴿٢﴾ ٱقۡرَأۡ وَرَبُّكَ ٱلۡأَكۡرَمُ ﴿٣﴾ ٱلَّذِي عَلَّمَ بِٱلۡقَلَمِ ﴿٤﴾ عَلَّمَ ٱلۡإِنسَٰنَ مَا لَمۡ يَعۡلَمۡ ﴿٥﴾", "id": "(1) Bacalah dengan (menyebut) nama Tuhanmu yang menciptakan (2) Dia telah menciptakan manusia dari segumpal darah (3) Bacalah, dan Tuhanmulah Yang Mahamulia (4) Yang mengajar (manusia) dengan pena (5) Dia mengajarkan manusia apa yang tidak diketahuinya", "lb": "QS. Al-'Alaq: 1-5 · terjemah Kemenag RI"}};

/* ========== DATA: teks hadis ========== */
var HADIS={"ahmad8952": {"ar": "إِنَّمَا بُعِثْتُ لِأُتَمِّمَ صَالِحَ الْأَخْلَاقِ", "id": "Sesungguhnya aku diutus hanya untuk menyempurnakan akhlak yang baik. (Pada sebagian riwayat lafaznya \"makarim al-akhlaq\", akhlak yang mulia.)", "lb": "HR. Ahmad no. 8952 dari Abu Hurairah, dinilai sahih (Syu'aib al-Arna'uth, al-Albani); juga dalam Al-Adab al-Mufrad no. 273 · terjemahan bebas"}, "muslim746": {"ar": "فَإِنَّ خُلُقَ نَبِيِّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ الْقُرْآنَ", "id": "Sesungguhnya akhlak Nabi Allah ﷺ adalah Al-Quran. (Ucapan Aisyah r.a. ketika ditanya tentang akhlak Nabi.)", "lb": "HR. Muslim no. 746 dari Aisyah r.a. · terjemahan bebas"}};
var turn=0;

/* ========== DATA: jawaban chatbot Tanya AI ========== */
var BOT=[
{k:['otentik','keaslian','palsu','salah cetak','tantangan'],a:"Keaslian Al-Quran dijaga Allah, dan didukung oleh tradisi penghafal yang tidak terputus serta mushaf standar yang menjadi rujukan semua cetakan.",ref:"QS. Al-Hijr: 9. Tantangan: QS. Al-Isra: 88, QS. Hud: 13, QS. Al-Baqarah: 23.",ay:["15:9", "17:88", "11:13", "2:23"],hd:[],um:"Dalam sains, klaim diuji dengan bukti yang bisa dicek ulang. Tantangan membuat semisal Al-Quran mengajak siapa pun membuktikan sendiri, dan sumber yang bisa diverifikasi lebih dipercaya daripada kabar tanpa rujukan.",so:"Jika ada kabar viral tentang salah cetak, masyarakat bisa mengeceknya karena banyak penghafal dan mushaf standar, tetapi tetap harus tabayun agar tidak menyebarkan hoaks."},
{k:['mushaf','utsman','usman','abu bakar','kodifikasi','zaid'],a:"Penulisan Al-Quran melewati tiga fase: masa Nabi (hafalan dan tulisan terpisah), masa Abu Bakar (dikumpulkan karena banyak penghafal wafat di perang Yamamah), dan masa Utsman (disatukan dalam satu mushaf agar bacaan seragam).",ref:"QS. Al-Hijr: 9.",ay:["15:9"],hd:[],um:"Menyatukan banyak catatan menjadi satu sumber standar mirip standarisasi data: semua salinan merujuk satu naskah induk agar konsisten.",so:"Penyatuan mushaf mencegah perselisihan bacaan dan menjaga persatuan kaum muslimin."},
{k:['mukjizat','maknawi','hissi','tongkat musa'],a:"Mukjizat adalah hal luar biasa yang Allah berikan kepada nabi sebagai bukti kenabian. Ada mukjizat hissi (terlihat panca indera, terbatas ruang dan waktu) dan ma'nawi (dipahami dengan akal, seperti Al-Quran yang abadi).",ref:"QS. Al-Baqarah: 23 dan QS. Hud: 37-38.",ay:["2:23", "11:37-38"],hd:[],um:"Mukjizat melampaui kebiasaan hukum alam (sunnatullah), sehingga tidak diuji dengan eksperimen sains yang meneliti keteraturan alam. Sains dan mukjizat berada di ranah yang berbeda.",so:"Mukjizat para nabi sesuai keunggulan zaman umatnya, misalnya sihir pada masa Musa, kedokteran pada masa Isa, dan sastra Arab pada masa Nabi Muhammad."},
{k:['makkiyah','madaniyah','makkah','madinah','juz','manzil'],a:"Ayat Makkiyah turun sebelum hijrah dan Madaniyah setelah hijrah. Makkiyah cenderung pendek dan membahas keimanan serta akhlak, sedangkan Madaniyah cenderung panjang dan memuat hukum serta aturan bermasyarakat. Al-Quran terdiri dari 114 surah dan 30 juz, dan manzil membaginya menjadi 7 bagian.",ref:"Contoh Makkiyah: QS. Al-Ikhlas dan An-Nas. Contoh Madaniyah: QS. Al-Baqarah dan Ali Imran.",um:"Pembagian juz dan manzil seperti manajemen waktu belajar: target kecil yang teratur membuat tugas besar lebih mudah diselesaikan.",so:"Di Makkah dakwah menguatkan fondasi iman dalam masyarakat yang menolak, sedangkan di Madinah umat membangun masyarakat dengan aturan sosial dan hukum."},
{k:['akhlak','teladan','budi pekerti','karakter'],a:"Akhlak adalah sifat yang tertanam dalam jiwa dan muncul spontan dalam perilaku. Nabi Muhammad diutus untuk menyempurnakan akhlak, dan Aisyah r.a. menyebut akhlak beliau adalah Al-Quran.",ref:"QS. Al-Qalam: 4, QS. Al-Ahzab: 21, dan hadis riwayat Ahmad no. 8952 dan Muslim no. 746.",ay:["68:4", "33:21"],hd:["ahmad8952", "muslim746"],um:"Psikologi belajar sosial menunjukkan orang cenderung meniru perilaku orang yang diteladani, sehingga keteladanan efektif membentuk karakter.",so:"Akhlak yang baik membangun kepercayaan, kerja sama, dan lingkungan sekolah serta masyarakat yang damai."},
{k:['teknologi','kedokteran','ilmuwan','ibnu sina','khawarizmi','fisika','kimia','matematika'],a:"Al-Quran mendorong belajar, dimulai dari perintah membaca, dan mengangkat derajat orang berilmu. Dalam sejarah, ilmuwan muslim seperti Ibnu Sina, Al-Khawarizmi, dan Ibnu Rusyd memberi sumbangan besar pada kedokteran, matematika, dan filsafat.",ref:"QS. Al-Alaq: 1-5 dan QS. Al-Mujadilah: 11.",ay:["96:1-5", "58:11"],hd:[],um:"Al-Khawarizmi dikenal lewat karya aljabar dan Ibnu Sina lewat kitab kedokterannya. Pengembangan ilmu butuh pengamatan, pencatatan, dan pengujian.",so:"Peradaban yang menghargai ilmu menumbuhkan sekolah, perpustakaan, dan pertukaran pengetahuan antarbangsa."},
{k:['air','hujan','sungai','laut'],a:"Air punya kedudukan penting dalam Al-Quran dan juga dalam ilmu pengetahuan.",ref:"QS. Al-Anbiya: 30, Allah menjadikan segala sesuatu yang hidup dari air.",ay:["21:30"],hd:[],um:"Semua sel makhluk hidup membutuhkan air sebagai pelarut dan tempat reaksi kimia. Siklus air (penguapan, pengembunan, hujan) menjaga ketersediaan air tawar.",so:"Permukiman manusia sejak dulu tumbuh dekat sungai. Krisis air bersih hari ini bisa memicu masalah kesehatan dan konflik antarwarga."},
{k:['hoaks','hoax','berita','informasi','tabayun','media sosial'],a:"Al-Quran mengajarkan untuk memeriksa kabar sebelum mempercayainya.",ref:"QS. Al-Hujurat: 6, perintah tabayun terhadap berita yang dibawa orang yang tidak jelas kejujurannya.",ay:["49:6"],hd:[],um:"Sikap ini sejalan dengan berpikir ilmiah: periksa sumber, cari bukti, dan bandingkan dengan data lain sebelum menyimpulkan.",so:"Di media sosial hoaks menyebar cepat dan bisa memecah belah masyarakat, sehingga kebiasaan tabayun melindungi diri dan lingkungan sekitar."},
{k:['lingkungan','sampah','banjir','polusi','pencemaran','hutan'],a:"Al-Quran mengingatkan bahwa manusia ikut bertanggung jawab atas kerusakan alam.",ref:"QS. Ar-Rum: 41, kerusakan di darat dan laut muncul akibat perbuatan manusia.",ay:["30:41"],hd:[],um:"Pencemaran dan penebangan hutan merusak ekosistem, dan sampah yang menyumbat sungai bisa memicu banjir.",so:"Banjir dan pencemaran berdampak pada pendapatan, kesehatan, dan hubungan sosial warga. Gotong royong dan aturan bersama membantu menjaga lingkungan."},
{k:['hafal','menghafal','tahfiz','otak','memori','ingat'],a:"Al-Quran dijaga Allah, salah satunya lewat tradisi hafalan umat Islam, dan Al-Quran dimudahkan untuk dipelajari.",ref:"QS. Al-Hijr: 9 dan QS. Al-Qamar: 17.",ay:["15:9", "54:17"],hd:[],um:"Penelitian tentang belajar menunjukkan pengulangan yang dijadwalkan dan tidur yang cukup membantu daya ingat. Hafalan juga lebih kuat bila dipahami maknanya.",so:"Tradisi halaqah dan tahfiz menunjukkan bagaimana komunitas belajar saling menguatkan dan menurunkan ilmu antargenerasi."},
{k:['semesta','langit','bintang','bumi','planet','dentuman'],a:"Al-Quran mengajak manusia memperhatikan langit dan bumi.",ref:"QS. Al-Anbiya: 30 dan QS. Adz-Dzariyat: 47.",ay:["21:30", "51:47"],hd:[],um:"Sains menjelaskan alam semesta lewat pengamatan, misalnya teori dentuman besar dan semesta yang mengembang. Sebagian orang mengaitkannya dengan ayat ini, tetapi ulama menafsirkan ayat dengan beragam cara, jadi kaitan ini sebagai bahan renungan, bukan penentu makna ayat.",so:"Rasa ingin tahu terhadap alam mendorong tradisi ilmu dan pengamatan di banyak peradaban, termasuk pada masa keemasan Islam."},
{k:['toleransi','beda','keragaman','suku','bangsa','masyarakat'],a:"Al-Quran menyebut manusia dijadikan berbangsa-bangsa dan bersuku-suku agar saling mengenal.",ref:"QS. Al-Hujurat: 13.",ay:["49:13"],hd:[],um:"Keanekaragaman hayati membantu ketahanan ekosistem, sehingga keberagaman bisa dipandang sebagai kekuatan.",so:"Indonesia adalah masyarakat majemuk. Sikap saling menghargai, dialog, dan kerja sama menjaga persatuan."},
{k:['belajar','membaca','iqra','ilmu','literasi','sains','ilmiah'],a:"Wahyu pertama memerintahkan manusia untuk membaca dan belajar.",ref:"QS. Al-Alaq: 1-5.",ay:["96:1-5"],hd:[],um:"Literasi sains melatih kita bertanya, mengamati, dan menguji gagasan dengan bukti.",so:"Masyarakat yang gemar membaca cenderung lebih mampu menyaring informasi dan mengambil keputusan bersama."}];
var SUG=["Mengapa air disebut asal kehidupan?","Bagaimana Al-Quran menyikapi berita hoaks?","Apa hubungan menghafal Al-Quran dengan cara kerja otak?","Bagaimana Al-Quran memandang keberagaman masyarakat?"];

/* ========== FUNGSI BANTU DAN TAMPILAN SISWA ========== */
function tot(x){return x.ai+x.m}
function now(){var d=new Date();return ('0'+d.getHours()).slice(-2)+':'+('0'+d.getMinutes()).slice(-2)}
function esc(s){return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/"/g,'&quot;')}
function fd(d){var x=new Date(d+'T00:00:00');return isNaN(x)?d:x.toLocaleDateString('id-ID',{day:'numeric',month:'short'})}
function targeted(t,s){var g=t.tg;return g.k==='all'||(g.k==='cls'&&g.c===s.c)||(g.k==='some'&&g.list.indexOf(s)>-1)}
function recipCount(t){var n=0;Object.keys(S).forEach(function(k){S[k].forEach(function(s){if(targeted(t,s))n++})});return n}
function lbl(t){var g=t.tg;if(g.k==='all')return 'Seluruh siswa X.1 sampai X.6';if(g.k==='cls')return 'Kelas '+g.c;return g.list.length+' siswi tertentu'}
function subOf(t,s){for(var i=0;i<SUB.length;i++)if(SUB[i].t===t.id&&SUB[i].s===s)return SUB[i];return null}
function join(a){return a.length>1?a.slice(0,-1).join(', ')+' dan '+a[a.length-1]:(a[0]||'')}
function ph(v){return v.replace(/[\s\-]/g,'')}
function phOk(v){return /^(\+62|62|0)8[0-9]{8,12}$/.test(v)}
function qr(){var n=21,c=160/n,s='',seed=7;function r(){seed=(seed*9301+49297)%233280;return seed/233280}
for(var y=0;y<n;y++)for(var x=0;x<n;x++){var on=r()>0.5;
[[0,0],[14,0],[0,14]].forEach(function(o){var dx=x-o[0],dy=y-o[1];if(dx>=-1&&dx<=7&&dy>=-1&&dy<=7){on=(dx>=0&&dx<=6&&dy>=0&&dy<=6)&&(dx==0||dx==6||dy==0||dy==6||(dx>=2&&dx<=4&&dy>=2&&dy<=4))}});
if(on)s+='<rect x="'+x*c+'" y="'+y*c+'" width="'+c+'" height="'+c+'"/>'}
return '<svg viewBox="0 0 160 160" width="160" height="160" fill="currentColor" shape-rendering="crispEdges" role="img" aria-label="Kode QR absensi"><title>Kode QR absensi</title>'+s+'</svg>'}
function rank(){return S['X.3'].slice().sort(function(a,c){return tot(c)-tot(a)})}
function render(){
var t=tot(me);
document.getElementById('h-tot').textContent=t;
document.getElementById('h-bar').style.width=t*10+'%';
document.getElementById('h-sub').textContent='Diskusi AI '+me.ai+'/3 · Dari guru '+me.m+'/7';
document.getElementById('a-n').textContent=me.ai;
document.getElementById('b-count').textContent=t;
var row='';for(var i=0;i<10;i++){var k=i<me.ai?'s-ai':(i<t?'s-gr':'s-off');row+='<span class="st '+k+'"><i class="ti ti-star" aria-hidden="true"></i></span>'}
document.getElementById('b-row').innerHTML=row;
document.getElementById('b-log').innerHTML=log.map(function(l){return '<div style="display:flex;gap:8px;align-items:center;padding:6px 0;border-bottom:0.5px solid var(--border)"><i class="ti '+CAT[l.c]+'" style="color:var(--text-accent)" aria-hidden="true"></i><span style="flex:1">'+l.c+'</span><span class="muted">'+l.t+'</span></div>'}).join('');
var b=rank(),pos=b.indexOf(me)+1;
document.getElementById('h-rank').textContent=pos;
document.getElementById('h-n').textContent=b.length;
var top=b.slice(0,5).map(function(x,i){return '<div style="display:flex;gap:8px;padding:6px 0;border-bottom:0.5px solid var(--border);'+(x===me?'font-weight:500;color:var(--text-accent)':'')+'"><span style="width:22px">'+(i+1)+'</span><span style="flex:1">'+esc(x===me?x.n+' (kamu)':x.n)+'</span></div>'}).join('');
document.getElementById('b-board').innerHTML=top+(pos>5?'<div style="padding:8px 0;font-weight:500;color:var(--text-accent)">Peringkatmu: '+pos+' dari '+b.length+'</div>':'')+'<div class="muted" style="padding-top:6px">Menampilkan 5 teratas</div>';
teacher()}
