/* ========== MODE GURU ========== */
function teacher(){
document.getElementById('chips').innerHTML=Object.keys(S).map(function(k){return '<button data-c="'+k+'" style="font-size:13px;'+(k===cls?'background:var(--bg-accent);color:var(--text-accent);border-color:var(--border-accent)':'')+'">Kelas '+k+'</button>'}).join('');
var L=S[cls];
document.getElementById('g-c').textContent=cls;
document.getElementById('g-cnt').textContent='· '+L.length+' siswi';
document.getElementById('g-h').textContent=L.filter(function(x){return x.p}).length+' / '+L.length;
document.getElementById('g-s').textContent=L.reduce(function(a,x){return a+x.m},0)+' / '+L.length*7;
document.getElementById('g-k').textContent=L.filter(function(x){return x.kon}).length+' / '+L.length;
var sel=document.getElementById('g-sel');
sel.innerHTML=L.map(function(x,i){return '<option value="'+i+'">'+esc(x.n)+' ('+x.m+'/7)</option>'}).join('');
sel.value=String(selIdx);
var q=document.getElementById('g-q').value.trim().toLowerCase();
var F=L.filter(function(x){return !q||x.n.toLowerCase().indexOf(q)>-1});
var shown=(q||showAll)?F:F.slice(0,8);
document.getElementById('g-more').textContent=showAll?'Tampilkan 8 pertama':'Tampilkan semua';
document.getElementById('g-more').style.display=q?'none':'';
document.getElementById('g-tb').innerHTML=shown.map(function(x){return '<tr><td>'+esc(x.n)+'</td><td>'+(x.p?'<span class="pill" style="background:var(--bg-success);color:var(--text-success)">Hadir</span>':'<span class="pill" style="background:var(--bg-danger);color:var(--text-danger)">Belum</span>')+'</td><td>'+x.ai+'</td><td>'+x.m+'</td><td>'+tot(x)+'</td><td>'+tot(x)*10+'</td><td>'+kPill(x)+'</td></tr>'}).join('')||'<tr><td colspan="7" class="muted">Nama tidak ditemukan</td></tr>'}
function homeExtra(){
var pend=T.filter(function(t){return targeted(t,me)&&!subOf(t,me)}).length;
document.getElementById('h-pend').textContent='Tugas belum dikumpulkan: '+pend;
var h='';
if(REM&&!me.kon)h+='<div class="card" style="border-color:var(--border-accent)"><div class="fl"><i class="ti ti-bell" style="color:var(--text-accent)" aria-hidden="true"></i><span style="flex:1;font-size:14px">Guru meminta kamu melengkapi kontak wali kelas dan orang tua atau wali.</span><button id="rem-go">Lengkapi sekarang</button></div></div>';
var mine=TEG.filter(function(x){return x.s===me});
if(mine.length)h+='<div class="card" style="border-color:var(--border-warning)"><div class="fl" style="margin-bottom:6px"><i class="ti ti-mail" style="color:var(--text-warning)" aria-hidden="true"></i><span style="font-weight:500;flex:1">Pesan pribadi dari guru</span><span class="muted">'+mine[0].time+'</span></div><div style="font-size:14px;white-space:pre-wrap">'+esc(mine[0].msg)+'</div>'+(mine[0].ccTo.length?'<div class="blk" style="background:var(--surface-1);color:var(--text-secondary)"><i class="ti ti-users" aria-hidden="true"></i> Tembusan pesan ini juga dikirim ke '+esc(join(mine[0].ccTo))+'.</div>':'')+'</div>';
document.getElementById('h-teg').innerHTML=h}
function sTugas(){
var L=T.filter(function(t){return targeted(t,me)});
document.getElementById('st-list').innerHTML=L.map(function(t){var s=subOf(t,me),st;
if(!s)st='<textarea id="ta-'+t.id+'" rows="4" style="width:100%;box-sizing:border-box;margin-top:10px" placeholder="Tulis jawaban tugasmu"></textarea><div class="err" id="te-'+t.id+'"></div><button data-send="'+t.id+'"><i class="ti ti-send" aria-hidden="true"></i> Kirim tugas</button>';
else if(s.grade===null)st='<div class="blk" style="background:var(--bg-accent);color:var(--text-accent);margin-top:10px"><i class="ti ti-clock" aria-hidden="true"></i> Terkirim '+esc(s.time)+'. Menunggu penilaian guru.</div>';
else st='<div class="blk" style="background:var(--bg-success);color:var(--text-success);margin-top:10px"><div style="font-weight:500;font-size:15px">Nilai: '+s.grade+' / 100</div>'+(s.note?'<div style="margin-top:2px">'+esc(s.note)+'</div>':'')+'</div>';
return '<div class="card"><div class="fl" style="margin-bottom:4px"><span style="font-weight:500;flex:1">'+esc(t.title)+'</span><span class="pill" style="background:var(--surface-1)">Tenggat '+fd(t.due)+'</span></div><div class="muted">'+esc(t.desc)+'</div>'+st+'</div>'}).join('')||'<div class="card muted">Belum ada tugas untukmu.</div>'}
