/* ===== TAMBAHAN R&K v12 ===== */
function $(i){return document.getElementById(i)}
var REV=[],SET=[],KQ={},OFF={},kb=0,ki=0,kShown=false,rec=null,chunks=[],blobUrl=null,pgAll=false;
try{OFF=JSON.parse(localStorage.getItem('rk_off')||'{}')}catch(e){OFF={}}
function pill(t,k){return '<span class="pill" style="background:var(--bg-'+k+');color:var(--text-'+(k==='accent'?'accent':k)+')">'+t+'</span>'}
/* 1. Kuis latihan */
function kuis(){var t=0,o=0;BAB.forEach(function(b,i){(KQ[i]||[]).forEach(function(v){t++;if(v)o++})});
$('k-sum').textContent=t?('Dipahami '+o+' dari '+t+' pertanyaan yang sudah kamu coba'):'Belum ada pertanyaan yang dicoba';
$('k-bab').innerHTML=BAB.map(function(b,i){return '<button class="bb'+(i===kb?' on':'')+'" data-kb="'+i+'">Bab '+b.n+'</button>'}).join('');
var b=BAB[kb],q=b.qs[ki],h='';
if(ki>=b.qs.length){var bad=[];(KQ[kb]||[]).forEach(function(v,i){if(!v)bad.push(i+1)});
h='<div class="blk" style="background:var(--bg-'+(bad.length?'warning':'success')+');color:var(--text-'+(bad.length?'warning':'success')+')">'+(bad.length?'Perlu diulang: pertanyaan nomor '+bad.join(', ')+'. Baca lagi materi Bab '+b.n+' (subbab: '+esc(b.sub.join('; '))+').':'Semua pertanyaan Bab '+b.n+' sudah kamu pahami.')+'</div><div class="fl" style="margin-top:8px"><button data-ka="mat">Buka materi Bab '+b.n+'</button><button data-ka="again">Ulangi kuis</button></div>'}
else{h='<div class="muted">Pertanyaan '+(ki+1)+' dari '+b.qs.length+'</div><div style="margin:6px 0;font-weight:500">'+esc(q.q)+'</div><textarea rows="3" style="width:100%;box-sizing:border-box" placeholder="Tulis jawabanmu dulu"></textarea>';
if(!kShown)h+='<button data-ka="show" style="margin-top:8px">Lihat jawaban rujukan</button>';
else h+='<div class="blk" style="background:var(--surface-1);margin-top:8px"><div>'+esc(q.a)+'</div><div class="muted">Rujukan: '+esc(q.ref)+'</div></div><div class="muted" style="margin:8px 0 4px">Bandingkan dengan jawabanmu. Bagaimana pemahamanmu?</div><div class="fl"><button data-ka="ok">Sudah paham</button><button data-ka="no">Perlu diulang</button></div>'}
$('k-body').innerHTML=h}
$('s-kuis').addEventListener('click',function(e){var b=e.target.closest('button');if(!b)return;
if(b.dataset.kb!==undefined){kb=+b.dataset.kb;ki=0;kShown=false;KQ[kb]=[]}
else{var a=b.dataset.ka;if(a==='show')kShown=true;else if(a==='ok'||a==='no'){(KQ[kb]=KQ[kb]||[])[ki]=a==='ok';ki++;kShown=false}
else if(a==='again'){ki=0;kShown=false;KQ[kb]=[]}else if(a==='mat'){go('materi');openMateri(kb,0)}}kuis()});
/* 2. Kemajuan siswi */
function kp(x){if(x===me){var t=0,o=0;for(var k in KQ)KQ[k].forEach(function(v){t++;if(v)o++});return t?Math.round(o/t*100):50}
var h=0;for(var i=0;i<x.n.length;i++)h=(h*31+x.n.charCodeAt(i))%101;return 20+h%76}
function lag(x){return x.miss>=3||x.late>=4||kp(x)<40}
function prog(){$('pg-c').textContent=cls;var L=S[cls].slice().sort(function(a,b){return (lag(b)-lag(a))||(kp(a)-kp(b))});
$('pg-n').textContent=L.filter(lag).length;
$('pg-tb').innerHTML=L.slice(0,pgAll?999:10).map(function(x){return '<tr><td>'+esc(x.n)+'</td><td>'+kp(x)+'%</td><td>'+x.miss+'</td><td>'+x.late+'</td><td>'+(lag(x)?pill('Tertinggal','warning'):pill('Aman','success'))+'</td></tr>'}).join('');
$('pg-all').textContent=pgAll?'Tampilkan 10 teratas':'Tampilkan semua'}
$('pg-all').addEventListener('click',function(){pgAll=!pgAll;prog()});
/* 3. Rujukan dan tinjauan guru */
var _ba=botAsk;botAsk=function(t){_ba(t);var r=botFind(t),c=$('bot-chat').lastChild;if(!c)return;
var b=document.createElement('button');b.textContent='Minta guru meninjau jawaban ini';b.style.marginTop='8px';
b.onclick=function(){REV.push({q:t,a:r?r.a:'(belum ada jawaban baku)',ref:r?r.ref:'',st:'baru',t:now()});b.disabled=true;b.textContent='Terkirim ke guru';tinjau()};c.appendChild(b)};
function tinjau(){$('tj-n').textContent=REV.filter(function(x){return x.st==='baru'}).length;
$('tj-list').innerHTML=REV.length?REV.map(function(x,i){return '<div class="row"><div class="muted">'+x.t+' · pertanyaan siswi</div><div style="font-weight:500">'+esc(x.q)+'</div><div style="font-size:13px;margin:4px 0">'+esc(x.a)+'</div><div class="muted">Rujukan: '+esc(x.ref)+'</div>'+(x.st==='baru'?'<div class="fl" style="margin-top:6px"><button data-rv="'+i+'|ok">Sudah benar</button><button data-rv="'+i+'|fix">Perlu koreksi</button></div>':'<div style="margin-top:6px">'+(x.st==='ok'?pill('Dinyatakan benar','success'):pill('Perlu koreksi','warning'))+'</div>')+'</div>'}).join(''):'<div class="muted">Belum ada jawaban AI yang dilaporkan.</div>'}
$('g-tinjau').addEventListener('click',function(e){var b=e.target.closest('button');if(!b||!b.dataset.rv)return;var p=b.dataset.rv.split('|');REV[+p[0]].st=p[1];tinjau()});
/* 4. Modul ajar dan soal */
$('a-bab').innerHTML=BAB.map(function(b,i){return '<option value="'+i+'">Bab '+b.n+': '+esc(b.t)+'</option>'}).join('');
$('a-m').addEventListener('click',function(){var B=BAB[+$('a-bab').value],M=MAT[+$('a-bab').value];
$('a-out').value='MODUL AJAR (DRAF AWAL)\nMata pelajaran: Al-Quran Hadis, Kelas X, MAN 3 Kota Makassar\nBab '+B.n+': '+B.t+'\n\nTujuan pembelajaran:\n'+M.tj.map(function(t,i){return (i+1)+'. '+t}).join('\n')+'\n\nPertanyaan pemantik:\n'+B.sample+'\n\nKeterkaitan dengan ilmu pengetahuan umum:\n'+B.um+'\n\nKeterkaitan dengan ilmu pengetahuan sosial:\n'+B.so+'\n\nKegiatan pembelajaran:\nPembuka: salam, doa, tilawah, pertanyaan pemantik.\nInti (per subbab):\n'+B.sub.map(function(s){return '- '+s}).join('\n')+'\nPenutup: refleksi, kuis latihan R&K, dan tugas.\n\nAsesmen:\n- Diskusi dengan AI dan bintang keaktifan\n- Kuis latihan dan setoran bacaan\n'});
$('a-s').addEventListener('click',function(){var B=BAB[+$('a-bab').value];
$('a-out').value='SOAL URAIAN BAB '+B.n+' (DRAF AWAL)\n\n'+B.qs.map(function(q,i){return (i+1)+'. '+q.q+'\nKunci jawaban: '+q.a+'\nRujukan: '+q.ref}).join('\n\n')});
$('a-cp').addEventListener('click',function(){var t=$('a-out');t.select();var ok=false;try{ok=document.execCommand('copy')}catch(e){}$('a-ok').textContent=ok?'Tersalin':'Blok teks lalu salin manual'});
/* 5. Setoran bacaan */
function setor(){if(!$('r-ay').options.length)$('r-ay').innerHTML=Object.keys(AYAT).map(function(k){return '<option value="'+k+'">QS '+k+'</option>'}).join('');
$('r-ar').textContent=AYAT[$('r-ay').value].ar;
var m=SET.filter(function(x){return x.s===me});
$('r-hist').innerHTML=m.length?m.map(function(x){return '<div class="row"><b>QS '+x.k+'</b> · '+x.t+'<br>'+(x.f?pill('Nilai '+x.f.n,'success')+' <span style="font-size:13px">'+esc(x.f.c)+'</span>':pill('Menunggu penilaian guru','warning'))+'</div>'}).join(''):'<div class="muted">Belum ada setoran.</div>'}
$('r-ay').addEventListener('change',setor);
$('r-rec').addEventListener('click',function(){var b=this;$('r-err').textContent='';
if(rec&&rec.state==='recording'){rec.stop();return}
if(!(navigator.mediaDevices&&window.MediaRecorder)){$('r-err').textContent='Perekaman tidak tersedia di perangkat ini. Kamu tetap bisa mengirim tanpa rekaman untuk mencoba alurnya.';return}
navigator.mediaDevices.getUserMedia({audio:true}).then(function(st){chunks=[];rec=new MediaRecorder(st);rec.ondataavailable=function(e){chunks.push(e.data)};
rec.onstop=function(){st.getTracks().forEach(function(t){t.stop()});blobUrl=URL.createObjectURL(new Blob(chunks));var a=$('r-au');a.src=blobUrl;a.style.display='';b.textContent='Rekam ulang'};rec.start();b.textContent='Berhenti'})
.catch(function(){$('r-err').textContent='Izin mikrofon ditolak. Kamu tetap bisa mengirim tanpa rekaman untuk mencoba alurnya.'})});
$('r-send').addEventListener('click',function(){SET.push({s:me,k:$('r-ay').value,u:blobUrl,t:now()});blobUrl=null;$('r-au').style.display='none';$('r-rec').textContent='Rekam';setor();gsetor()});
function gsetor(){$('gs-list').innerHTML=SET.length?SET.map(function(x,i){return '<div class="row"><div style="font-weight:500">'+esc(x.s.n)+' · QS '+x.k+' · '+x.t+'</div><div class="ar" style="font-size:20px">'+esc(AYAT[x.k].ar)+'</div>'+(x.u?'<audio controls src="'+x.u+'" style="width:100%"></audio>':'<div class="muted">Dikirim tanpa rekaman (demo)</div>')+(x.f?'<div style="margin-top:6px">'+pill('Nilai '+x.f.n,'success')+' '+esc(x.f.c)+'</div>':'<div class="fl" style="margin-top:6px"><select data-sc="'+i+'"><option>Lancar dan tepat</option><option>Perlu perbaiki tajwid</option><option>Perlu perbaiki makhraj</option><option>Perlu diulang</option></select><input data-sn="'+i+'" type="number" min="0" max="100" value="80" style="width:90px"><button data-sk="'+i+'">Kirim penilaian</button></div>')+'</div>'}).join(''):'<div class="muted">Belum ada setoran bacaan.</div>'}
$('g-setor').addEventListener('click',function(e){var b=e.target.closest('button');if(!b||b.dataset.sk===undefined)return;var i=+b.dataset.sk;
SET[i].f={n:Math.max(0,Math.min(100,+document.querySelector('[data-sn="'+i+'"]').value||0)),c:document.querySelector('[data-sc="'+i+'"]').value};gsetor();setor()});
