function offl(){$('o-net').textContent=navigator.onLine?'Terhubung ke internet':'Sedang offline: materi tersimpan tetap bisa dibaca';
$('o-list').innerHTML=BAB.map(function(b,i){var kb2=Math.round(JSON.stringify(MAT[i]).length/1024);return '<div class="row fl"><div style="flex:1;min-width:160px"><b>Bab '+b.n+'</b> '+esc(b.t)+'<div class="muted">'+kb2+' KB teks</div></div>'+(OFF[i]?pill('Tersimpan','success')+'<button data-of="'+i+'|r">Hapus</button>':'<button data-of="'+i+'|s">Simpan offline</button>')+'<button data-of="'+i+'|b">Baca</button></div>'}).join('')}
$('s-offline').addEventListener('click',function(e){var b=e.target.closest('button');if(!b||!b.dataset.of)return;var p=b.dataset.of.split('|'),i=+p[0];
if(p[1]==='b'){go('materi');openMateri(i,0);return}
try{if(p[1]==='s'){localStorage.setItem('rk_mat'+i,JSON.stringify(MAT[i]));OFF[i]=1}else{localStorage.removeItem('rk_mat'+i);delete OFF[i]}localStorage.setItem('rk_off',JSON.stringify(OFF))}catch(x){if(p[1]==='s')OFF[i]=1;else delete OFF[i]}offl()});
