/* ===== TAMPILAN ELEGAN v13 ===== */
function tab(v){var t={home:1,materi:1,bot:1,kuis:1,guru:1}[v]?v:'more';document.querySelectorAll('#tabbar button').forEach(function(b){var on=b.dataset.t===t;b.classList.toggle('on',on);b.setAttribute('aria-current',on?'page':'false')})}
function stack(o,n){o.style.cssText='display:block;position:absolute;left:0;right:0;top:'+n.offsetTop+'px;pointer-events:none;transform-origin:50% 0';
var a=o.animate([{transform:'perspective(1100px) translateZ(0) rotateX(0deg)',opacity:1},{transform:'perspective(1100px) translateZ(-180px) rotateX(9deg) scale(.95)',opacity:0}],{duration:420,easing:'cubic-bezier(.4,0,.2,1)',fill:'forwards'});
a.onfinish=function(){a.cancel();o.style.cssText=''};
n.animate([{transform:'perspective(1100px) translateY(70px) translateZ(80px) rotateX(-7deg)',opacity:0},{transform:'perspective(1100px) translateY(0) translateZ(0) rotateX(0deg)',opacity:1}],{duration:520,easing:'cubic-bezier(.2,.8,.2,1)'})}
var _go3=go;go=function(v){var o=document.querySelector('.scr.on');_go3(v);tab(v);var n=document.querySelector('.scr.on');
if(o&&n&&o!==n&&o.animate&&!(window.matchMedia&&matchMedia('(prefers-reduced-motion:reduce)').matches))stack(o,n);window.scrollTo(0,0)};
document.getElementById('tabbar').addEventListener('click',function(e){var b=e.target.closest('button');if(b)go(b.dataset.t)});
document.getElementById('s-more').addEventListener('click',function(e){var b=e.target.closest('[data-go]');if(b)go(b.dataset.go)});
